/* High-yield grouped past-paper questions from AC68–AC79 (deduplicated and grouped across years).
   Loaded after past6.js and before lecq.js so past-paper MCQs stay together before lecture quizzes. */
(function () {
  CVS.after('N-C1', [
    { id: 'N1', src: 'AC73–79', q: 'What is the group of neuronal cells in the PNS called?', o: ['Tract', 'Nucleus', 'Ganglion', 'Gray matter', 'White matter'], a: 2, ex: 'A cluster of neuronal cell bodies is called a ganglion in the PNS and a nucleus in the CNS. Bundles of axons are called nerves in the PNS and tracts in the CNS.' },
    { id: 'N2', src: 'AC73–79', q: 'What is the bundle of nerve fibers that has a proper direction in the CNS?', o: ['Tract', 'Nucleus', 'Ganglion', 'Gray matter', 'White matter'], a: 0, ex: 'An organized bundle of axons sharing an origin and destination in the CNS is a tract (in the PNS it is a nerve). Nuclei and ganglia are collections of cell bodies.' }
  ]);
  CVS.after('N-C2', [
    { id: 'N6', src: 'AC78', q: 'Which of the following is a characteristic of dendrites?', o: ['Length vary from microns to meters', 'Surface varies from smooth to spiny', 'They are often myelinated', 'Branching limited to collaterals', 'Transport impulses from the cell body'], a: 1, ex: 'Dendrites are short, unmyelinated, extensively branched receptive processes whose surfaces range from smooth to studded with dendritic spines, carrying signals toward the soma. The other four statements describe axons.' },
    { id: 'N7', src: 'AC73–79', q: 'What is a Nissl granule?', o: ['Centriole', 'Ribosome', 'Microtubule', 'Golgi apparatus', 'RER'], a: 4, ex: 'Nissl bodies (granules) are basophilic clumps of rough endoplasmic reticulum (RER) studded with polyribosomes in the soma and dendrites, reflecting intense protein synthesis.' },
    { id: 'N8', src: 'AC73–79', core: true, q: 'Which cytoplasmic organelle cannot be found in an axon?', o: ['RER', 'Vesicle', 'Microtubule', 'Mitochondria', 'Neurofilament'], a: 0, ex: 'Rough ER (Nissl bodies) and Golgi are confined to the soma and dendrites and stop at the axon hillock, so the axon relies on axonal transport for new proteins. Microtubules, neurofilaments, mitochondria and vesicles are abundant in the axon.' },
    { id: 'N9', src: 'AC73–79', q: 'Which of the following cytoplasmic organelles is responsible for vesicle formation?', o: ['Microtubule', 'Neurofilament', 'Centriole', 'Golgi apparatus', 'Endoplasmic reticulum'], a: 3, ex: 'The Golgi apparatus modifies proteins received from the RER and packages them into transport and secretory vesicles. Microtubules then carry those vesicles down the axon.' }
  ]);
  CVS.after('N-C3', [
    { id: 'N11', src: 'AC73 · AC74 · AC76', core: true, q: 'Which of the following cytoplasmic organelles plays a role in axonal transport?', o: ['Golgi apparatus', 'Microtubule', 'Microfilament', 'Neurofilament', 'Centriole'], a: 1, ex: 'Microtubules form the tracks along the axon on which kinesin (anterograde) and dynein (retrograde) motor proteins haul vesicles and organelles. Neurofilaments provide structural calibre.' },
    { id: 'N12', src: 'AC78', core: true, q: 'Poliomyelitis is caused by poliovirus, resulting in several neuropathies in the central nervous system. How does the poliovirus enter the central nervous system?', o: ['Blood', 'Lymph', 'Transneuronal transport', 'Anterograde axonal transport', 'Retrograde axonal transport'], a: 4, ex: 'Poliovirus (like rabies, HSV and tetanus toxin) enters motor nerve terminals and rides dynein along microtubules back to the CNS soma via retrograde axonal transport.' },
    { id: 'N13', src: 'AC76', q: 'Which one of the following can be found at the synaptic bouton of the presynaptic neuron?', o: ['Vesicle of neurotransmitter', 'Neurotransmitter receptors', 'Nissl body', 'Synaptic cleft', 'Dendritic spine'], a: 0, ex: 'The presynaptic axon terminal (synaptic bouton) is packed with synaptic vesicles and mitochondria ready for exocytosis. Receptors and dendritic spines sit on the postsynaptic side; Nissl bodies are absent from axons.' }
  ]);
  CVS.after('N-C4', [
    { id: 'N14', src: 'AC73 · AC74 · AC76 · AC77', core: true, q: 'Which cell is responsible for myelin sheath synthesis in the peripheral nervous system?', o: ['Astrocyte', 'Oligodendrocyte', 'Microglia', 'Satellite cell', 'Schwann cell'], a: 4, ex: 'Schwann cells myelinate peripheral axons (one Schwann cell forms one internode of a single axon). Oligodendrocytes myelinate axons in the CNS.' },
    { id: 'N15', src: 'AC73–79', q: 'Which of the following cells is responsible for myelin formation in the central nervous system?', o: ['Astrocyte', 'Microglia', 'Schwann cell', 'Ependymal cell', 'Oligodendrocyte'], a: 4, ex: 'Oligodendrocytes extend multiple processes to myelinate segments of several axons in the CNS. Schwann cells perform this role in the PNS.', flag: 'Option B was printed as “Microcyte” in the recall; corrected to Microglia.' }
  ]);
  CVS.after('N-C5', [
    { id: 'N25', src: 'AC73', q: 'Which of the following cells is one of the components of the blood–brain barrier?', o: ['Microglia', 'Astrocyte', 'Schwann cell', 'Ependymal cell', 'Oligodendrocyte'], a: 1, ex: 'Astrocyte perivascular end-feet envelop CNS capillaries and induce tight junctions between endothelial cells, forming a key component of the blood–brain barrier.' },
    { id: 'N26', src: 'AC75 · AC76', q: 'Which cell is responsible for scar formation in the brain?', o: ['Astrocyte', 'Oligodendrocyte', 'Microglia', 'Ependymal cell', 'Schwann cell'], a: 0, ex: 'After CNS injury, reactive astrocytes proliferate and lay down a glial scar (astrogliosis) to wall off damaged tissue.' },
    { id: 'N27', src: 'AC77', core: true, q: 'Which cell will transform into a choroid plexus?', o: ['Astrocyte', 'Oligodendrocyte', 'Microglia', 'Ependymal cell', 'Schwann cell'], a: 3, ex: 'Ependymal cells line the ventricles and central canal; modified ependymal epithelium over vascular pia mater forms the choroid plexus, which secretes cerebrospinal fluid (CSF).' },
    { id: 'N28', src: 'AC78', q: 'Which of the following is not a function of astrocytes?', o: ['Produce neurotrophic factors necessary for neuronal survival', 'Blood–brain barrier', 'Provide growth factors required for regeneration of neurons in the CNS', 'Electrolyte balance of the CNS', 'Form scars resulting from CNS injury'], a: 2, ex: 'Astrocytes maintain CNS K⁺/ion homeostasis, support the BBB, secrete neurotrophic factors and form glial scars. They do not promote CNS neuronal regeneration; their glial scars inhibit axonal regrowth (Schwann cells support regeneration in the PNS).', flag: 'The old AC79 compiled key erroneously attributed CNS regeneration growth factors to oligodendrocytes; neither astrocytes nor oligodendrocytes promote CNS regeneration.' },
    { id: 'N29', src: 'AC73–79', q: 'Which cell is found in the PNS?', o: ['Oligodendrocyte', 'Satellite cell', 'Astrocyte', 'Microglia', 'Ependymal cell'], a: 1, ex: 'The two PNS glial types are Schwann cells (around axons) and satellite cells (around neuronal cell bodies in ganglia). Astrocytes, oligodendrocytes, microglia and ependymal cells are CNS glia.', flag: 'Option D was printed as “Microcyte” in the recall; corrected to Microglia.' },
    { id: 'N30', src: 'AC73–79', q: 'A 10-year-old girl has severed her radial nerve. Which cell plays a major role in axonal regrowth?', o: ['Fibroblast', 'Schwann cell', 'Oligodendrocyte', 'Fibrous astrocyte', 'Protoplasmic astrocyte'], a: 1, ex: 'The radial nerve is a peripheral nerve. After peripheral axotomy, Schwann cells proliferate to form guiding cords (bands of Büngner) and secrete neurotrophic factors that support axonal regeneration.' },
    { id: 'N31', src: 'AC73–79', q: 'A 6-year-old boy died of viral encephalitis. Which type of cell should be increased in his brain tissue?', o: ['Astroglia', 'Microglia', 'Satellite cell', 'Schwann cell', 'Oligodendrocyte'], a: 1, ex: 'Microglia are the resident immune/phagocytic cells of the CNS; during brain infection and inflammation (viral encephalitis), they proliferate and migrate to phagocytose debris and pathogens.' },
    { id: 'N32', src: 'AC73–79', q: 'Axon regeneration in the CNS is prohibited by which type of cells?', o: ['Microglia', 'Astrocyte', 'Satellite cell', 'Ependymal cell', 'Oligodendrocyte'], a: 1, ex: 'Reactive astrocytes form a dense glial scar containing inhibitory proteoglycans that physically and chemically block CNS axonal regrowth.', flag: 'Oligodendrocyte myelin proteins (e.g. Nogo) also inhibit CNS axonal regrowth in vivo; the course key emphasizes the astrocyte glial scar.' }
  ]);
  CVS.after('N-C6', [
    { id: 'N34', src: 'AC73 · AC74', core: true, q: 'Which receptor is responsible for detection of pressure and vibration?', o: ['Merkel cell', 'Pacinian corpuscle', 'Meissner corpuscle', 'End bulb of Krause', 'Neuromuscular spindle'], a: 1, ex: 'Pacinian (lamellar) corpuscles sit deep in the dermis and hypodermis and rapidly adapt to detect deep pressure and high-frequency vibration. Meissner and Merkel endings sense light touch.' },
    { id: 'N35', src: 'AC73–79', q: 'Which is a pain receptor?', o: ['Merkel cell', 'Free nerve ending', 'End bulb of Krause', 'Pacinian corpuscle', 'Meissner’s corpuscle'], a: 1, ex: 'Unencapsulated free nerve endings in the epidermis and tissues act as nociceptors (pain) and thermoreceptors (temperature).' },
    { id: 'N36', src: 'AC73–79', q: 'Which receptor initiates the stretch reflex?', o: ['Neuromuscular spindle', 'Meissner’s corpuscle', 'Pacinian corpuscle', 'Merkel’s disk', 'End bulb of Krause'], a: 0, ex: 'Neuromuscular (muscle) spindles lie in parallel with extrafusal fibres, detect changes in muscle length, and trigger the stretch reflex.' }
  ]);
  CVS.after('M-C2', [
    { id: 'M3', src: 'AC76 · AC77 · AC78', core: true, q: 'A patient came to the hospital with confusion and fatigue. A test showed a normal resting membrane potential of −70 mV. What is the relative concentration of Na⁺ and K⁺ in this patient?', o: ['[K⁺]in &lt; [K⁺]out, [Na⁺]in &lt; [Na⁺]out', '[K⁺]in &gt; [K⁺]out, [Na⁺]in &gt; [Na⁺]out', '[K⁺]in = [K⁺]out, [Na⁺]in = [Na⁺]out', '[K⁺]in &gt; [K⁺]out, [Na⁺]in &lt; [Na⁺]out', '[K⁺]in &lt; [K⁺]out, [Na⁺]in &gt; [Na⁺]out'], a: 3, ex: 'A normal resting membrane potential relies on the gradients maintained by the Na⁺/K⁺-ATPase: high intracellular K⁺ ([K⁺]in &gt; [K⁺]out) and high extracellular Na⁺ ([Na⁺]in &lt; [Na⁺]out).', flag: 'The AC79 compiled key for item 2 erroneously marked option B ([Na⁺]in &gt; [Na⁺]out); AC76 and AC77 keys and physiology confirm [K⁺]in &gt; [K⁺]out and [Na⁺]in &lt; [Na⁺]out.' },
    { id: 'M4', src: 'AC71', q: 'Which step during the generation and recovery of an axonal action potential is directly energy-dependent (requires ATP)?', o: ['Restore ion concentration', 'Generating after-hyperpolarization', 'Inactivation of sodium channel', 'Depolarizing membrane potential to threshold level', 'Opening of voltage-controlled channels'], a: 0, ex: 'Depolarization, channel gating, repolarization and after-hyperpolarization are all passive ion fluxes down electrochemical gradients. Only restoring the Na⁺ and K⁺ concentration gradients via the Na⁺/K⁺-ATPase consumes ATP.' }
  ]);
  CVS.after('M-C3', [
    { id: 'M7', src: 'AC76', core: true, q: 'Which of the following is correct about membrane potential?', o: ['Equilibrium potential can be calculated by the Nernst equation.', 'Equilibrium potential is calculated when concentration gradient and electrical force is parallel and equal.', 'Concentration gradient and electrical force are always opposite.', 'Equilibrium potential is affected by temperature in degree Celsius.', 'Equilibrium potential is determined by membrane thickness.'], a: 0, ex: 'The Nernst equation gives a single ion’s equilibrium potential, where chemical and electrical forces are equal and opposite (not parallel). At rest for Na⁺, both forces point inward, so they are not always opposite. Nernst uses absolute temperature in Kelvin and does not depend on membrane thickness.' },
    { id: 'M8', src: 'AC77 · AC78', q: 'A 70-year-old woman has low oral water intake, flushed skin, low-grade fever and confusion. Serum sodium is 167 mEq/L (normal 135–145 mEq/L). Was there any change in the elements of the Goldman equation? If yes, what has changed?', o: ['No, there have been no changes.', 'Yes, the intracellular sodium level was increased.', 'Yes, the extracellular sodium level was increased.', 'Yes, permeability of the membrane was increased.', 'Yes, the valency of ion was increased.'], a: 2, ex: 'Serum sodium reflects extracellular Na⁺ concentration ([Na⁺]o), which appears directly in the numerator of the Goldman–Hodgkin–Katz equation; hypernatremia increases [Na⁺]o.' },
    { id: 'M9', src: 'AC73–79', q: 'Which of the following factors has an effect on the equilibrium potential of Na⁺ through the electrical force?', o: ['Temperature', 'Valence', 'Permeability', 'Concentration of intracellular ion', 'Concentration of extracellular ion'], a: 1, ex: 'In the Nernst equation E = (RT/zF) ln([X]o/[X]i), the electrical work term is zFE, so ion valence (z) governs the electrical force; temperature and concentrations set the chemical force, and permeability does not affect equilibrium potential.' }
  ]);
  CVS.after('M-C4', [
    { id: 'M13', src: 'AC76 · AC77', core: true, q: 'Intravenous amiodarone homogeneously prolongs ventricular repolarization in patients with life-threatening ventricular tachyarrhythmia. What happens in the repolarization phase of the action potential?', o: ['Voltage-gated Na⁺ channels are inactivated, voltage-gated K⁺ channels are activated.', 'Voltage-gated Na⁺ channels are activated, voltage-gated K⁺ channels are inactivated.', 'Voltage-gated Na⁺ channels are activated, voltage-gated K⁺ channels are activated.', 'Voltage-gated Na⁺ channels are inactivated, voltage-gated K⁺ channels are inactivated.', 'Voltage-gated Ca²⁺ channels are activated, non-gated K⁺ channels are inactivated.'], a: 0, ex: 'Repolarization occurs because voltage-gated Na⁺ channels inactivate (halting Na⁺ influx) while voltage-gated K⁺ channels open (driving K⁺ efflux back toward resting potential).' },
    { id: 'M14', src: 'AC75', q: 'A 40-year-old man suffered from tingling and numbness after eating pufferfish. Which stage of the action potential is affected?', o: ['Repolarization', 'Depolarization', 'Hyperpolarization', 'Electrotonic potential', 'Return to resting stage'], a: 1, ex: 'Pufferfish contains tetrodotoxin (TTX), which blocks voltage-gated Na⁺ channels and prevents the rapid Na⁺ influx responsible for depolarization.', flag: 'AC75 Q25 recalled the toxin name as “tetracyclin” (a typo for tetrodotoxin); the cleaner pufferfish stem from the AC73–79 compiled pool is shown here.' },
    { id: 'M15', src: 'AC75', q: 'Tetrodotoxin interferes with which transmembrane flux of ions?', o: ['Sodium influx', 'Sodium efflux', 'Calcium efflux', 'Potassium influx', 'Potassium efflux'], a: 0, ex: 'Tetrodotoxin blocks voltage-gated Na⁺ channels, stopping the inward rush of Na⁺ (sodium influx) that drives the action potential upstroke.' },
    { id: 'M16', src: 'AC75', q: 'A 50-year-old man presents with numbness and is confirmed to have tetrodotoxin poisoning. What factor is altered by tetrodotoxin?', o: ['Threshold of action potential', 'Amplitude of action potential', 'After hypo-polarization period', 'After hyper-polarization period', 'Absolute and relative refractory period'], a: 0, ex: 'Blocking a fraction of voltage-gated Na⁺ channels means a larger depolarization is required to open enough remaining channels to trigger the positive-feedback upstroke, so the action potential threshold rises (becomes harder to reach).', flag: 'Physiologically, partial Na⁺-channel block also lowers AP amplitude and complete block abolishes APs altogether; the exam keyed “Threshold of action potential” (higher/harder threshold to fire).' },
    { id: 'M17', src: 'AC73–79', q: 'Which factor is altered by a prolonged depolarization and repolarization phase?', o: ['All-or-none property', 'Threshold of action potential', 'Amplitude of action potential', 'After-hyperpolarization period', 'Absolute and relative refractory period'], a: 4, ex: 'The absolute refractory period covers depolarization and early repolarization (Na⁺ channels inactivated), and the relative refractory period covers late repolarization. Prolonging these phases lengthens both refractory periods.' }
  ]);
  CVS.after('M-C5', [
    { id: 'M27', src: 'AC78', q: 'A patient presents to the ER with muscle weakness, tall peaked T-waves and a prolonged PR interval. Her serum potassium is 7 mmol/L (normal 3.5–5 mmol/L). Which of the following events is likely for this patient?', o: ['RMP is less positive. Action potential fires more frequently and has taller amplitude.', 'RMP is less positive. Na⁺–K⁺ ATPase activity is higher.', 'RMP is less positive. Action potential has shorter amplitude.', 'RMP is more positive. Neurons are desensitized.', 'RMP is more positive. Refractory period becomes shorter.'], a: 3, ex: 'Severe hyperkalemia (7 mmol/L) reduces the K⁺ gradient, making E<sub>K</sub> and the resting membrane potential less negative (more positive). Sustained depolarization keeps voltage-gated Na⁺ channels inactivated, so excitable cells become desensitized (depolarization block).' }
  ]);
  CVS.after('P-C1', [
    { id: 'P1', src: 'AC70', q: 'Which is a consequence of increasing membrane resistance (Rm)?', o: ['Time constant is increased', 'Length constant is increased', 'The specific cytoplasmic resistance is decreased', 'The axonal membrane conductance is decreased'], a: 1, ex: 'Because λ = √(Rm / Ra), raising membrane resistance (as myelin does) prevents current leakage and increases the length constant so depolarization spreads farther down the axon.', flag: 'Mathematically, increasing Rm alone also increases τ = Rm·Cm and decreases conductance (1/Rm); the exam keyed “Length constant is increased” because in myelination Cm drops while Rm rises, making longer λ the key effect.' },
    { id: 'P2', src: 'AC71', q: 'What electrophysiological change occurs due to demyelination in Guillain–Barré syndrome?', o: ['Increase axonal resistance', 'Increase length constant', 'Decrease time constant', 'Increase membrane capacitance', 'Increase membrane resistance'], a: 3, ex: 'Myelin thickens the insulating layer, which keeps membrane capacitance (Cm) low and membrane resistance (Rm) high. Demyelination strips that insulation, so Cm increases, Rm decreases, and length constant falls.' },
    { id: 'P3', src: 'AC72', core: true, q: 'A man presents with a recent respiratory infection, muscle pain, lower-limb weakness, decreased muscle tone, flaccidity, absent tendon reflexes, facial weakness and nerve demyelination. Which property decreases?', o: ['Axial resistance', 'Axial capacitance', 'Membrane resistance', 'Membrane capacitance', 'Membrane conductance'], a: 2, ex: 'In Guillain–Barré syndrome, loss of myelin allows current to leak across the internodal membrane, so membrane resistance (Rm) decreases (while membrane conductance 1/Rm and capacitance Cm increase).' },
    { id: 'P4', src: 'AC74', q: 'A patient has had high blood glucose for 8 years and develops diabetic neuropathy. Which of the following is the most likely electrophysiological consequence of this disease process?', o: ['More negative membrane potential', 'Delayed activation phase of action potential', 'Persistent inactivation of voltage-controlled sodium channel', 'Decreased length constant and increased time constant caused by nerve damage', 'Increased threshold for end-plate potential'], a: 3, ex: 'Diabetic neuropathy causes segmental demyelination: lower Rm cuts the length constant (λ), while the sharp rise in membrane capacitance slows membrane charging (longer time constant), slowing conduction.' }
  ]);
  CVS.after('P-C2', [
    { id: 'P10', src: 'AC72 · AC76 · AC79', core: true, q: 'A man presents after a respiratory infection with muscle pain, progressive ascending weakness of the lower limbs, flaccidity, areflexia, facial weakness, sensory disturbance and peripheral nerve demyelination. What is the most likely diagnosis?', o: ['Myasthenia gravis', 'Multiple sclerosis', 'Lambert–Eaton myasthenic syndrome', 'Guillain–Barré syndrome', 'Diabetes mellitus'], a: 3, ex: 'Post-infectious ascending flaccid paralysis with areflexia and peripheral demyelination is classic Guillain–Barré syndrome (GBS). MS affects CNS myelin; MG and LEMS are NMJ disorders without demyelination or sensory loss.', flag: 'The old AC70–75 yellow key mistakenly highlighted Multiple Sclerosis for AC72 Q9; AC76 and AC79 confirm Guillain–Barré syndrome.' },
    { id: 'P11', src: 'AC78', q: 'A 73-year-old man presents with weakness and sensory disturbance of both extremities. Peripheral demyelination is found and Guillain–Barré syndrome is diagnosed. Which process is affected in this patient?', o: ['Continuous conduction of peripheral nerve', 'Release of neurotransmitter', 'Saltatory conduction of peripheral nerve', 'Affinity of neurotransmitter in postsynaptic neuron', 'Summation of electrical signal in axon hillock'], a: 2, ex: 'Myelinated peripheral nerves rely on saltatory conduction (jumping from node to node). Demyelination in GBS disrupts saltatory conduction, slowing or blocking impulse propagation.' },
    { id: 'P12', src: 'AC78', q: 'An 88-year-old woman complains of intractable hiccups and frequent vomiting. Immunofluorescence shows autoimmune attack against aquaporin-4 protein. What is the most likely diagnosis?', o: ['Myasthenia gravis', 'Neuromyelitis optica', 'Multiple sclerosis', 'Guillain–Barré syndrome', 'Diabetic neuropathy'], a: 1, ex: 'Neuromyelitis optica (NMO) is caused by anti-AQP4 antibodies targeting astrocyte end-feet in the optic nerves, spinal cord and area postrema (causing intractable hiccups and vomiting).' }
  ]);
  CVS.after('P-C3', [
    { id: 'P15', src: 'AC68 · AC74', core: true, q: 'A 60-year-old woman complains of frequent muscular weakness and easy fatigability. Her anti-acetylcholine receptor antibody assay is 44.85 nmol/L (normal &lt;0.4) and CT shows thymic hypertrophy. Which physiological variable is reduced?', o: ['The amplitude of action potential in nerve', 'The frequency of action potential in nerve', 'The conductance of Ca²⁺ channel of nerve', 'The amplitude of end-plate potential in muscle', 'The open probability of acetylcholine receptor of muscle'], a: 3, ex: 'In myasthenia gravis, antibodies reduce the number of functional postsynaptic nAChRs, so each nerve impulse produces a smaller end-plate potential (EPP) that may fail to reach threshold for a muscle AP. Presynaptic nerve APs and Ca²⁺ influx remain normal.' },
    { id: 'P16', src: 'AC70', q: 'A 20-year-old woman develops blurry vision, dysphagia, dysarthria and laboured breathing after eating home-canned vegetables. A toxin acting at the presynaptic NMJ membrane is suspected. Which of the following is reduced?', o: ['Peak amplitude of compound nerve action potential', 'Open probability of end-plate acetylcholine channel', 'Conductance of open end-plate Ca²⁺ channel', 'The total number of open end-plate acetylcholine channels', 'Driving force on ions inducing an action potential'], a: 3, ex: 'Botulinum toxin blocks presynaptic ACh vesicle release, so far less ACh reaches the end-plate and the total number of open postsynaptic nAChR channels falls, preventing an adequate EPP. The nerve AP itself is unaffected.' }
  ]);
  CVS.after('P-C4', [
    { id: 'P21', src: 'AC70 · AC73', q: 'After eating home-canned vegetables at her grandmother’s farm, a 20-year-old woman develops blurry vision, difficulty swallowing and speaking, and laboured breathing. The toxin acts on the presynaptic membrane at the NMJ. What is the toxin?', o: ['Tetrodotoxin', 'Tetanus toxin', 'Botulinum toxin', 'Alpha-latrotoxin', 'Alpha-bungarotoxin'], a: 2, ex: 'Improperly home-canned food causes botulism: botulinum toxin acts presynaptically to block ACh release, producing descending flaccid paralysis (bulbar palsy then respiratory failure).' },
    { id: 'P22', src: 'AC79', core: true, q: 'A 20-year-old woman eats vegetables canned by her grandmother and develops food poisoning from a toxin that inhibits presynaptic ACh release. What is the underlying mechanism of this toxin?', o: ['Inhibits inhibitory neurotransmitters', 'Degrades SNARE complex', 'Blocks voltage-gated calcium channels', 'Degrades neurexins', 'Blocks voltage-gated sodium channels'], a: 1, ex: 'Botulinum toxin is a protease that cleaves SNARE proteins in motor nerve terminals, stopping synaptic vesicles from fusing with the presynaptic membrane to release ACh.' },
    { id: 'P23', src: 'AC71 · AC77', q: 'A patient experiences ptosis, diplopia, dysphagia and muscle weakness after being bitten by a snake. What is the toxin causing these symptoms?', o: ['α-Bungarotoxin', 'α-Latrotoxin', 'Tetrodotoxin', 'Cobra venom', 'Botulinum toxin'], a: 0, ex: 'α-Bungarotoxin (from kraits, Bungarus species) binds irreversibly to postsynaptic nAChRs at the NMJ, causing cranial-nerve-first flaccid paralysis (ptosis, diplopia, dysphagia, respiratory weakness).', flag: 'Note that cobra venom also contains postsynaptic nAChR neurotoxins (α-cobratoxin); the exam keyed the specific named toxin α-bungarotoxin from the lecture toxin table.' },
    { id: 'P24', src: 'AC71', q: 'A patient develops progressive flaccid paralysis after a krait snake bite (α-bungarotoxin). Which of the following diseases shares the same target receptor/channel with this toxin?', o: ['Poliomyelitis', 'Myasthenia gravis', 'Guillain–Barré syndrome', 'Centronuclear myopathy', 'Lambert–Eaton myasthenic syndrome'], a: 1, ex: 'Both α-bungarotoxin and myasthenia gravis antibodies target the postsynaptic nicotinic acetylcholine receptor (nAChR) on the motor end-plate. LEMS targets presynaptic Ca²⁺ channels.' },
    { id: 'P25', src: 'AC72 · AC79', core: true, q: 'A 65-year-old woman followed for small cell lung cancer develops progressive lower-extremity weakness over one month. Anti-acetylcholine receptor antibodies are negative, and electrodiagnostic studies show a presynaptic NMJ disorder. What is the most likely diagnosis?', o: ['Multiple sclerosis', 'Myasthenia gravis', 'Diabetic neuropathy', 'Guillain–Barré syndrome', 'Lambert–Eaton myasthenic syndrome'], a: 4, ex: 'Small cell lung cancer + proximal/lower-limb weakness + negative anti-AChR antibodies + presynaptic NMJ defect is classic Lambert–Eaton myasthenic syndrome (LEMS, anti-VGCC antibodies).', flag: 'AC70–75 yellow key erroneously marked Diabetic neuropathy, and AC79 initially listed NMO before correcting to LEMS; LEMS is unequivocally correct.' },
    { id: 'P26', src: 'AC72 · AC78', q: 'A 65-year-old woman with small cell lung cancer has progressive lower-extremity weakness, negative anti-AChR antibodies, and a presynaptic NMJ disorder. What pathophysiology explains her symptoms?', o: ['Excessive secretion of acetylcholine', 'Decreased probability of opening ACh receptor', 'Blocked acetylcholine secretion by blocking voltage-gated Ca²⁺ channels'], a: 2, ex: 'In LEMS, autoantibodies attack presynaptic P/Q-type voltage-gated Ca²⁺ channels, reducing Ca²⁺ influx and impairing ACh vesicle release.', flag: 'Only three options were recalled.' },
    { id: 'P27', src: 'AC79', q: 'A man previously diagnosed with thymic hyperplasia now experiences fluctuating muscle weakness, ptosis, diplopia and dysphagia. What is the most likely diagnosis?', o: ['Multiple sclerosis', 'Neuromyelitis optica', 'Guillain–Barré syndrome', 'Myasthenia gravis', 'Lambert–Eaton myasthenic syndrome'], a: 3, ex: 'Thymic hyperplasia (or thymoma) combined with fatigable, fluctuating ocular and bulbar weakness (ptosis, diplopia, dysphagia) is textbook myasthenia gravis.' },
    { id: 'P28', src: 'AC79', q: 'A man experiences fatigue, dysphagia, muscle weakness and monotone speech. Serum NMO-IgG is negative. What is the likely underlying cause of his symptoms?', o: ['Autoimmune attack on AQP4', 'Pre-existing respiratory infection', 'Internalization of nAChR', 'White blood cell damages myelin causing multiple scarring', 'Pre-existing gastrointestinal infection'], a: 2, ex: 'Fatigable bulbar weakness (dysphagia, monotone speech) with negative NMO-IgG points to myasthenia gravis, where anti-nAChR antibodies cross-link and cause internalization/degradation of postsynaptic nicotinic receptors.', flag: 'Stem was reconstructed from lecture cases in the AC79 recall (classic MG presentation).' },
    { id: 'P29', src: 'AC75', q: 'A patient develops unopposed muscle spasm and rigidity caused by a toxin that suppresses inhibitory neurotransmitter release. Which cell/neuron is the target?', o: ['Renshaw cell', 'Glial cell', 'Schwann cell', 'Alpha motor neuron', 'Gamma motor neuron'], a: 0, ex: 'Tetanus toxin (tetanospasmin) travels retrogradely to spinal cord inhibitory interneurons (such as Renshaw cells) and blocks inhibitory transmitter release, leaving α-motor neurons uninhibited → spastic paralysis and rigidity.' },
    { id: 'P30', src: 'AC77', q: 'What is the mechanism of action of a toxin that attacks the Renshaw cell?', o: ['Inhibit GABA release', 'Inhibit acetylcholine release', 'Enhance glutamate release', 'Inhibit glycine release', 'Enhance serotonin release'], a: 0, ex: 'Tetanus toxin cleaves SNARE proteins in spinal inhibitory interneurons (including Renshaw cells), blocking release of inhibitory neurotransmitters (glycine and GABA) and causing spastic paralysis.', flag: 'Physiologically, tetanus toxin blocks BOTH glycine and GABA release, and Renshaw cells use glycine as their primary neurotransmitter (making D even more specific than A). The AC77 key marked A (Inhibit GABA release), so remember both glycine and GABA are inhibited.' }
  ]);
  CVS.after('P-C5', [
    { id: 'P33', src: 'AC75 · AC76', core: true, q: 'A 10-year-old boy accidentally drinks chlorpyrifos, an organophosphate insecticide. Which of the following is the medicinal classification of this agent?', o: ['Acetylcholinesterase', 'Acetylcholinesterase inhibitor', 'Acetylcholine receptor inhibitor', 'Non-depolarizing agent', 'Two-phase depolarizing agent'], a: 1, ex: 'Organophosphates (like chlorpyrifos) irreversibly inhibit acetylcholinesterase (AChE), causing ACh to accumulate at NMJ and autonomic synapses (cholinergic crisis and eventual depolarizing weakness).' },
    { id: 'P34', src: 'AC70', q: 'Which of the following drugs would be chosen from this list to counter NMJ paralysis caused by reduced ACh release (botulinum toxin)?', o: ['Neostigmine', 'Dantrolene', 'Succinylcholine', 'Tubocurarine', 'Atracurium'], a: 0, ex: 'Neostigmine is a reversible AChE inhibitor that preserves ACh in the synaptic cleft to enhance postsynaptic stimulation. Dantrolene (RyR1 blocker), succinylcholine (depolarizing blocker), tubocurarine and atracurium (non-depolarizing blockers) all worsen muscle weakness.', flag: 'Clinically, botulism is treated with equine antitoxin and ventilatory support (neostigmine has minimal efficacy in botulism compared with myasthenia gravis), but neostigmine is the only pro-cholinergic drug among the options.' }
  ]);
  CVS.after('L-C3', [
    { id: 'L3', src: 'AC76 · AC79', core: true, q: 'วัด nerve conduction velocity ใช้ขั้วไฟฟ้า 2 ตำแหน่ง อันหนึ่งห่างจากจุดวัด 340 mm อีกอันหนึ่งห่างจากจุดวัด 40 mm อันแรกใช้เวลา 10 ms อันที่สองใช้เวลา 4 ms หา nerve conduction velocity ตอบในหน่วย m/s (Two stimulation electrodes are 340 mm and 40 mm from the recording site, with latencies of 10 ms and 4 ms. What is the nerve conduction velocity in m/s?)', o: ['56 m/s', '75 m/s', '60 m/s', '50 m/s'], a: 3, ex: 'Subtract both distances and latencies to eliminate synaptic/recording delay: Δd = 340 − 40 = 300 mm = 0.30 m; Δt = 10 − 4 = 6 ms = 0.006 s; NCV = 0.30 / 0.006 = 50 m/s.', flag: 'In AC76 Q10 the distances were recalled as 34 mm and 4 mm (dropped a zero) with the same 50 m/s answer; AC79 gives the exact values (340 mm and 40 mm).' }
  ]);
  CVS.after('L-C4', [
    { id: 'L5', src: 'AC76 · AC79', core: true, q: 'เรียงลำดับขั้วไฟฟ้า A, B, C, D ในชุดทดลองวัด compound action potential ของเส้นประสาทกบให้ถูกต้อง (Identify electrodes A, B, C, D in the frog nerve chamber setup in order.)', fig: CVS.fig('ac79-elec', 'AC79: frog sciatic nerve chamber electrode positions A–D.', 'ac79', 14), o: ['Ground, Recording Electrodes, Anode, Cathode', 'Ground, Recording Electrodes, Cathode, Anode', 'Recording Electrodes, Ground, Cathode, Anode', 'Recording Electrodes, Ground, Anode, Cathode'], a: 1, ex: 'From distal to proximal on the frog nerve chamber: A (green) = Ground, B (white) = Recording Electrodes, C (black, closer to recording) = Cathode (−, initiates depolarization), D (red, farthest) = Anode (+).' },
    { id: 'L6', src: 'AC79', core: true, q: 'During frog sciatic nerve stimulation, if the cathode and anode are switched (placing the anode between the cathode and the recording electrodes), what is expected?', o: ['Decreased latency period, Increased CAP', 'Decreased latency period, Decreased CAP', 'Increased latency period, Increased CAP', 'Increased latency period, Decreased CAP'], a: 3, ex: 'Placing the anode closer to the recording electrode creates a hyperpolarized zone between the cathode and the recorder (anodal block). Conduction slows (increased latency) and some fibres fail to pass (decreased CAP amplitude).' }
  ]);
  CVS.after('L-C5', [
    { id: 'L10', src: 'AC75 · AC76', q: 'กระตุ้น sciatic nerve หลังหยดสาร succinylcholine / acetylcholine เข้มข้นน้อย / acetylcholine เข้มข้นมาก ที่ NMJ ของกบ ผลที่ได้เป็นอย่างไร (+ คือเกิด muscle contraction) (Sciatic nerve stimulation after applying succinylcholine / low-dose ACh / high-dose ACh to a frog NMJ: what are the muscle contraction results?)', o: ['+/+/+', '+/−/+', '−/+/+', '−/+/−', '−/−/−'], a: 3, ex: 'Low-dose ACh mimics normal transmission and produces contraction (+). Both succinylcholine and high-dose ACh cause persistent end-plate depolarization that inactivates voltage-gated Na⁺ channels, blocking contraction upon nerve stimulation (−).' },
    { id: 'L11', src: 'AC79', q: 'หากหยด succinylcholine (X) และ high-dose acetylcholine (Y) ไปที่ NMJ ของกบ 2 ตัว ตัวละ 1 ชนิด สารใดบ้างเกิด muscle fasciculation (If succinylcholine (X) and high-dose ACh (Y) are each applied to separate frog NMJs, which causes muscle fasciculation?)', o: ['X (Succinylcholine)', 'Y (High-dose ACh)', 'Both of them', 'Neither of them'], a: 0, ex: 'Succinylcholine causes a classic two-phase depolarizing block: Phase I triggers uncoordinated depolarization and visible muscle fasciculations before Phase II desensitization/paralysis sets in.', flag: 'Physiologically, high-dose ACh also causes an initial brief muscle contraction before depolarizing block (see Lab quiz), but the exam keyed succinylcholine alone because Phase I muscle fasciculation is the hallmark teaching point of succinylcholine.' }
  ]);
  CVS.after('R-C1', [
    { id: 'R1', src: 'AC68 · AC70 · AC75 · AC77', core: true, q: 'Stepping on a nail and pulling the foot away as a reflex is of which type?', o: ['Monosynaptic reflex', 'Disynaptic reflex', 'Polysynaptic reflex', 'Autonomic reflex', 'Crossed-extensor reflex'], a: 2, ex: 'The flexor withdrawal reflex routes nociceptive input through multiple spinal interneurons to excite flexors and inhibit extensors, making it a polysynaptic reflex. Stretch reflex is monosynaptic; tendon reflex is disynaptic.' },
    { id: 'R2', src: 'AC74', q: 'Which one is NOT part of the spinal reflex arc?', o: ['Pain receptor', 'Sciatic nerve', 'Hypothalamus', 'Motor nerve of spinal cord'], a: 2, ex: 'The five elements of a spinal reflex arc are receptor, afferent fibre, spinal integrating centre, efferent fibre and effector. The hypothalamus lies in the diencephalon and is not part of the spinal reflex arc.', flag: 'Only four options were recalled.' }
  ]);
  CVS.after('R-C2', [
    { id: 'R6', src: 'AC79', core: true, q: 'Which structure is not included in the stretch reflex arc?', o: ['Type Ia afferent neuron', 'Muscle spindle', 'Muscle fiber', 'Inhibitory interneuron', 'Motor neuron'], a: 3, ex: 'The stretch reflex is monosynaptic: muscle spindle → Type Ia afferent → direct excitatory synapse on α-motor neuron → extrafusal muscle fibre. An inhibitory interneuron belongs to the disynaptic tendon reflex (and reciprocal inhibition of the antagonist).' },
    { id: 'R7', src: 'AC76', q: 'Why can the stretch reflex conduct its electrical signal faster than the tendon reflex?', o: ['Afferent pathway is faster', 'Efferent pathway is faster', 'Stretch reflex is controlled by the CNS', 'Receptor of the stretch reflex is faster'], a: 0, ex: 'The stretch reflex uses thick, fast Type Ia afferents with a single synapse (monosynaptic), whereas the tendon reflex uses slightly slower Type Ib afferents plus an extra inhibitory interneuron (disynaptic).', flag: 'Only four options were recalled.' }
  ]);
  CVS.after('R-C3', [
    { id: 'R10', src: 'AC71', q: 'ข้อความใดถูกต้องเกี่ยวกับ flexor reflex และ crossed extensor reflex (Which statement is correct regarding the flexor reflex and crossed extensor reflex?)', o: ['ทั้งคู่เป็น deep tendon reflex (Both are deep tendon reflexes)', 'Crossed extensor reflex เป็น withdrawal reflex (Crossed extensor is a withdrawal reflex)', 'บางครั้ง crossed extensor reflex เกิดเร็วกว่า flexor reflex (Crossed extensor sometimes occurs faster than flexor)', 'Flexor reflex มี after-discharge สั้นกว่า crossed extensor reflex (Flexor has a shorter afterdischarge than crossed extensor)', 'สำหรับ crossed extensor reflex มี sensory neuron ต่อกับ motor neuron ไขสันหลังฝั่งตรงข้าม (Sensory neuron synapses directly on contralateral motor neuron)'], a: 3, ex: 'The crossed extensor reflex begins 0.2–0.5 s after the flexor reflex and has an even longer afterdischarge so the opposite limb keeps supporting body weight while the injured foot stays lifted. Both are polysynaptic cutaneous/nociceptive reflexes mediated via interneurons.' },
    { id: 'R11', src: 'AC74', q: 'Which of the following is a property of the flexor withdrawal reflex?', o: ['There is no afterdischarge', 'It is an example of a disynaptic reflex', 'The reflex is located on a tendon', 'Crossed extensor reflex occurs concurrently', 'Reflex occurs when the brain receives pain perception'], a: 3, ex: 'The flexor withdrawal reflex is a polysynaptic cutaneous spinal reflex (does not require brain perception), has prolonged afterdischarge via reverberating circuits, and is accompanied by the crossed extensor reflex in the opposite limb.' },
    { id: 'R12', src: 'AC78', q: 'When a person steps on a nail, which option is incorrect?', o: ['The reflex is called flexor–crossed-extensor reflex', 'Flexor thigh muscles of the ipsilateral leg are contracted', 'Extensor thigh muscles of the ipsilateral leg are contracted', 'This reflex is classified as a polysynaptic reflex', 'Inhibitory neurotransmitters such as GABA play an important role in this reflex'], a: 2, ex: 'On the injured (ipsilateral) side, flexors contract while extensors are relaxed via reciprocal inhibition so the foot pulls up. It is the contralateral extensors that contract to bear weight.' }
  ]);
  CVS.after('R-C4', [
    { id: 'R15', src: 'AC70 · AC71 · AC72 · AC79', core: true, q: 'Which statement is correct regarding spinal shock?', o: ['Humans recover within 2–3 days', 'It affects only the somatic nervous system and not the ANS', 'Upon recovery from spinal shock, reflexes become hyperreflexia', 'Incomplete spinal transection takes longer to recover than complete transection', 'Spinal shock is a permanent disorder'], a: 2, ex: 'Spinal shock is temporary (weeks to months in humans; hours in non-primates), depresses both somatic and autonomic reflexes below the lesion (complete transection takes longer), and resolves into hyperreflexia (with the stretch reflex returning first).', flag: 'In AC79 Q38 the recalled options omitted “after recovery” and pitted “Spinal shock leads to hyperreflexia” (keyed) against “hyporeflexia”. Remember the sequence: DURING acute spinal shock = areflexia/hyporeflexia; AFTER recovery = hyperreflexia.' },
    { id: 'R16', src: 'AC78', q: 'During a brief period of spinal shock, what is likely to happen?', o: ['During spinal shock, if the biceps reflex is absent, the knee jerk reflex can be completely normal', 'During spinal shock, most reflexes are isoreflexia', 'Deep tendon reflex is the first reflex to recover after the shock', 'During spinal shock, most reflexes are hyperreflexia', 'During spinal shock, most reflexes are hyporeflexia'], a: 4, ex: 'During the acute phase of spinal shock, sudden loss of descending facilitatory drive causes depression or loss of reflexes (hyporeflexia/areflexia) at and below the lesion. Hyperreflexia develops only later after recovery.' },
    { id: 'R17', src: 'AC73', core: true, q: 'A 45-year-old woman presents with a 2-week history of progressive muscle weakness of her right upper limb. Which finding indicates that her symptoms are caused by a central nervous system (UMN) lesion?', o: ['Areflexia of right upper limb', 'Hyporeflexia of right upper limb', 'Spasticity of right upper limb', 'Flaccidity of right upper limb', 'Right upper limb muscle atrophy'], a: 2, ex: 'Spasticity (and hyperreflexia) is a hallmark upper motor neuron / CNS sign caused by loss of descending inhibition. Areflexia, hyporeflexia, flaccidity and early muscle atrophy are lower motor neuron / PNS signs.', flag: 'Old recall PDFs (AC70–75 &amp; AC76–78) mistakenly keyed A (Areflexia); areflexia is a classic PNS/LMN sign, whereas spasticity (C) is the true CNS/UMN sign.' },
    { id: 'R18', src: 'AC73', q: 'An 18-year-old man presents with a 2-month history of progressive generalized muscle weakness accompanied by sensory loss and areflexia of all limbs. Which is the most likely cause?', o: ['Disease of brainstem', 'Disease of brachial plexus', 'Disease of multiple nerves', 'Disease of multiple muscles', 'Disease of cervical spinal cord'], a: 2, ex: 'Progressive weakness + sensory loss + generalized areflexia in all four limbs over 2 months indicates polyneuropathy (disease of multiple peripheral nerves, damaging both sensory afferents and LMN efferents). A chronic cervical cord lesion causes UMN hyperreflexia below the lesion; myopathy spares sensation.', flag: 'Old recall PDFs (AC70–75 &amp; AC76–78) mistakenly keyed E (Disease of cervical spinal cord); a 2-month cervical cord lesion would produce UMN hyperreflexia/spasticity below the lesion rather than generalized areflexia of all limbs.' },
    { id: 'R19', src: 'AC73 · AC74', core: true, q: 'Which of the following conditions is the cause of hyperreflexia of the deep tendon reflex of the quadriceps muscle?', o: ['Damage to sciatic nerve', 'Damage to L2 to L4', 'Damage to L5 to S1', 'Decreased activity of muscle spindle in quadriceps', 'Increased activity of gamma motoneuron in lumbar spinal cord'], a: 4, ex: 'Increased γ-motor neuron discharge tightens intrafusal fibres and heightens muscle spindle sensitivity, producing hyperreflexia. Damaging L2–L4 (the patellar reflex centre) or reducing spindle activity causes hyporeflexia.', flag: 'AC70–75 yellow key erroneously highlighted B (L2–L4 damage causes hyporeflexia); AC76–78 correctly keyed E.' },
    { id: 'R20', src: 'AC78', q: 'A man sustains a spinal injury after a severe car accident. Biceps and triceps tendon reflexes are normal, but the knee jerk reflex is absent bilaterally. Which level of the spinal cord is most likely injured?', o: ['Cervical', 'Thoracic', 'Lumbar', 'Sacral', 'Coccygeal'], a: 2, ex: 'Normal biceps (C5–C6) and triceps (C7–C8) reflexes rule out a cervical lesion. Bilateral loss of the knee jerk points directly to its reflex centre in the lumbar spinal cord (L2–L4).', flag: 'In acute spinal shock immediately after trauma, a thoracic cord injury can also transiently abolish the knee jerk before it turns hyperreflexic; the exam keyed Lumbar (L2–L4 reflex centre).' },
    { id: 'R21', src: 'AC79', q: 'หลังผ่านช่วง spinal shock พบว่า biceps reflex และ triceps reflex ปกติ แต่ knee jerk และ ankle reflex มี hyperreflexia แสดงว่าบาดเจ็บที่ระดับใด (After recovery from spinal shock, biceps and triceps reflexes are normal, while knee jerk and ankle reflexes show hyperreflexia. Which spinal level is injured?)', o: ['Upper cervical vertebrae', 'Lower cervical vertebrae', 'Thoracic vertebrae', 'Lumbar vertebrae', 'Sacral vertebrae'], a: 2, ex: 'Hyperreflexia occurs below an upper motor neuron lesion. Because both biceps (C5–C6) and triceps (C7–C8) are completely normal while L2–L4 (knee) and S1–S2 (ankle) are hyperreflexic, the lesion lies between C8 and L2: the thoracic cord.', flag: 'The AC79 student key erroneously selected Lower cervical by quoting a lecture example where biceps was absent (C5–C6 lesion). With both biceps and triceps normal, the lesion must be below C8 → Thoracic.' }
  ]);
  CVS.after('R-C5', [
    { id: 'R24', src: 'AC75', q: 'Regarding deep tendon reflex (DTR) testing, which statement is incorrect?', o: ['The test is done with a rubber hammer percussion at the right position.', 'The muscle tested must be relaxed.', 'The result can be compared to the other side.', 'The result can be compared with other subjects.', 'The test can be done while the subject is unconscious.'], a: 3, ex: 'Normal DTR briskness varies widely between healthy individuals, so you always compare symmetry left versus right in the same patient rather than comparing across different subjects. Because DTRs are spinal reflexes, they can be tested in unconscious patients.' }
  ]);
  CVS.after('R-C6', [
    { id: 'R26', src: 'AC79', core: true, q: 'Which reflex is this test examining in a 20-year-old man?', fig: CVS.fig('ac79-babinski', 'AC79: plantar stimulation test showing toe dorsiflexion and fanning.', 'ac79', 15), o: ['Jendrassik reflex', 'Babinski reflex', 'Cremasteric reflex', 'Patellar reflex'], a: 1, ex: 'Stroking the lateral border of the sole from heel toward the base of the toes tests the plantar (Babinski) reflex (S1–S2). Dorsiflexion of the big toe with fanning of the other toes is a positive Babinski sign.' },
    { id: 'R27', src: 'AC79', q: 'What is the interpretation of the positive Babinski response shown above in a 20-year-old man?', fig: CVS.fig('ac79-babinski', 'AC79: plantar stimulation test showing toe dorsiflexion and fanning.', 'ac79', 15), figRef: 'R26', o: ['Normal', 'Abnormal', 'Inconclusive'], a: 1, ex: 'In an adult (20-year-old man), the normal plantar response is toe plantarflexion (down-going). A positive Babinski sign (dorsiflexion + fanning) is abnormal and indicates an upper motor neuron / corticospinal (pyramidal) tract lesion; it is only normal in infants under ~1 year.' },
    { id: 'R28', src: 'AC79', q: 'What happens to the pupils during the accommodation reflex?', o: ['Dilation', 'Constriction', 'No change'], a: 1, ex: 'Shifting gaze from far to near triggers the accommodation triad: pupillary constriction (miosis, to increase depth of field), convergence of both eyes, and lens thickening.' }
  ]);
  CVS.after('A-C1', [
    { id: 'A1', src: 'AC75 · AC76', core: true, q: 'A patient with hypertension is treated with hexamethonium. Which receptor is inhibited by this medication?', o: ['Dopaminergic receptor', 'Beta adrenergic receptor', 'Alpha adrenergic receptor', 'Nicotinic cholinergic receptor', 'Muscarinic cholinergic receptor'], a: 3, ex: 'Hexamethonium is a ganglionic blocker: it selectively inhibits the neuronal nicotinic cholinergic (N2 / NN) receptor on postganglionic neurons in both sympathetic and parasympathetic ganglia, blocking fast EPSPs.' }
  ]);
  CVS.after('A-C2', [
    { id: 'A5', src: 'AC73', core: true, q: 'A 20-year-old man stabbed in the lateral left neck develops left facial dryness (anhidrosis) and ptosis from sympathetic nerve injury. Which neurotransmitter is normally released by the dysfunctional fibers that cause his facial dryness?', o: ['Nicotine', 'Glutamate', 'Acetylcholine', 'Norepinephrine', 'Phenylephrine'], a: 2, ex: 'Eccrine sweat glands are the classic exception to the sympathetic golden rule: their postganglionic sympathetic fibers are cholinergic and release acetylcholine onto M3 receptors (and the preganglionic sympathetic fibers injured in the neck also release ACh).', flag: 'The AC73 recall key erroneously listed D (Norepinephrine), overlooking that sympathetic innervation to eccrine sweat glands (as well as all preganglionic fibers) uses acetylcholine.' },
    { id: 'A6', src: 'AC73–79', core: true, q: 'A man ingests an organophosphate insecticide, which inhibits acetylcholinesterase. Which of the following is stimulated?', o: ['GI motility', 'Eccrine sweat gland', 'Heart rate', 'GI motility and eccrine sweat gland', 'Eccrine sweat gland and heart rate'], a: 3, ex: 'Inhibiting AChE floods cholinergic synapses with ACh. Excess ACh stimulates GI motility (parasympathetic M3) and eccrine sweat glands (sympathetic cholinergic M3), while slowing heart rate (vagal M2).' },
    { id: 'A7', src: 'AC78', q: 'A neurotransmitter induces contraction of the iris radial muscle, resulting in mydriasis. Which of the following processes is also mediated by this neurotransmitter?', o: ['Contraction of the smooth muscle in urinary bladder', 'Relaxation of the internal urinary sphincter', 'Constriction of the external urinary sphincter', 'Secretion of saliva from the salivary gland', 'Stimulation of eccrine sweat gland'], a: 3, ex: 'The iris radial (dilator) muscle contracts via norepinephrine on α1 receptors. NE also stimulates salivary glands (scant, viscous saliva via α1/β). Bladder contraction and internal sphincter relaxation are parasympathetic, external sphincter constriction is somatic (ACh), and eccrine sweat glands are sympathetic cholinergic (ACh).', flag: 'AC78 keys D (salivary secretion via sympathetic NE), whereas the AC79 recall key chose E (eccrine sweat glands), which conflicts with the course golden rule that eccrine sweat glands are cholinergic (ACh).' }
  ]);
  CVS.after('A-C3', [
    { id: 'A9', src: 'AC76', core: true, q: 'Which part of the autonomic nervous system is comparable to the adrenal medulla?', o: ['Postganglionic neuron of sympathetic nervous system', 'Preganglionic neuron of sympathetic nervous system', 'Postganglionic neuron of parasympathetic nervous system', 'Preganglionic neuron of parasympathetic nervous system', 'Target organ'], a: 0, ex: 'Chromaffin cells of the adrenal medulla are modified sympathetic postganglionic neurons: they receive direct sympathetic preganglionic cholinergic (ACh → N2) input and release epinephrine/norepinephrine into the bloodstream.' },
    { id: 'A10', src: 'AC73 · AC74', q: 'A 35-year-old woman has panic-like attacks, palpitations and blood pressure of 240/130 mmHg caused by an adrenal medulla tumor (pheochromocytoma). Pheochromocytoma escalates activity of which nervous system?', o: ['Enteric nervous system', 'Sympathetic nervous system', 'Parasympathetic nervous system', 'Sympathetic and parasympathetic nervous systems', 'Enteric, sympathetic and parasympathetic nervous systems'], a: 1, ex: 'Pheochromocytoma is a chromaffin-cell tumor of the adrenal medulla that secretes excess catecholamines (epinephrine and norepinephrine), mimicking massive sympathetic nervous system activation.' }
  ]);
  CVS.after('A-C4', [
    { id: 'A12', src: 'AC75 · AC76 · AC77 · AC78', core: true, q: 'A patient has an adrenal medulla tumor (pheochromocytoma) causing excessive catecholamine secretion. Which of the following muscles will have increased contractility?', o: ['Ciliary muscle', 'Iris sphincter muscle', 'Superior tarsal muscle', 'Levator palpebrae superioris muscle', 'Orbicularis oculi'], a: 2, ex: 'The superior tarsal (Müller’s) muscle is smooth muscle supplied by sympathetic α1 receptors, so excess catecholamines increase its tone (lid retraction). Ciliary and iris sphincter are parasympathetic (CN III); levator palpebrae (CN III) and orbicularis oculi (CN VII) are skeletal muscles.' },
    { id: 'A13', src: 'AC75', q: 'Which of the following can increase heart rate?', o: ['Volume loss', 'Decreased sympathetic activity', 'Decreased SA node activity', 'Increased parasympathetic activity', 'Loss of function of lateral hypothalamus'], a: 0, ex: 'Volume loss drops venous return and blood pressure, unloading arterial baroreceptors; the baroreceptor reflex then increases sympathetic outflow and decreases vagal tone to raise heart rate.' }
  ]);
  CVS.after('A-C5', [
    { id: 'A16', src: 'AC75 · AC76', core: true, q: 'An 80-year-old man presents with loss of bladder control and urethral sphincter function. Which nervous system(s) control micturition and the urinary sphincters?', o: ['Somatic nervous system only', 'Sympathetic nervous system only', 'Parasympathetic nervous system only', 'Sympathetic and parasympathetic nervous systems', 'Sympathetic, parasympathetic and somatic nervous systems'], a: 4, ex: 'All three act together: sympathetic (hypogastric nerve) relaxes the detrusor and contracts the internal sphincter for storage; parasympathetic (pelvic splanchnic nerve) contracts the detrusor for voiding; somatic (pudendal nerve) gives voluntary control of the external urethral sphincter.' }
  ]);
  CVS.after('A-C6', [
    { id: 'A19', src: 'AC74 · AC75 · AC77', core: true, q: 'A 10-year-old boy comes to the ER with dyspnea and is diagnosed with acute asthma. His heart rate is 130 bpm. Which of the following drugs should be prescribed?', o: ['Methanol', 'Salbutamol', 'Propranolol', 'Isoproterenol', 'Atropine'], a: 1, ex: 'Salbutamol (albuterol) is a selective β2 agonist that relaxes airway smooth muscle with minimal cardiac β1 stimulation. Isoproterenol (non-selective β1/β2 agonist) would worsen his tachycardia; propranolol (non-selective β-blocker) would worsen bronchospasm.' },
    { id: 'A20', src: 'AC76', q: 'Which one of the following drugs generally should NOT be administered to a patient with asthma?', o: ['Atropine', 'Propranolol', 'Epinephrine', 'Salbutamol', 'Isoproterenol'], a: 1, ex: 'Propranolol is a non-selective β1/β2 antagonist; blocking bronchial β2 receptors removes sympathetic bronchodilation and can precipitate severe bronchospasm. Epinephrine, salbutamol and isoproterenol stimulate β2, and atropine blocks muscarinic bronchoconstriction.' },
    { id: 'A21', src: 'AC77 · AC78', core: true, q: 'A woman drinks organophosphate insecticide and develops vomiting, diarrhea and hypersalivation. Drug X is given to block neurotransmitter Y. What is Drug X’s mechanism, and which muscle increases contractility due to neurotransmitter Y?', o: ['β-2 receptor antagonist / Gastrointestinal sphincter muscle', 'Muscarinic receptor antagonist / Gastrointestinal sphincter muscle', 'β-2 receptor antagonist / Cardiac muscle', 'Muscarinic receptor antagonist / Iris sphincter muscle', 'β-1 receptor antagonist / Cardiac muscle'], a: 3, ex: 'Organophosphates inhibit AChE, causing excess acetylcholine (Y). The muscarinic emergency antidote (X, atropine) is a muscarinic receptor antagonist. Excess ACh contracts the iris sphincter (miosis) and GI wall while relaxing GI sphincters and slowing the heart.' },
    { id: 'A22', src: 'AC76', q: 'A patient with benign prostatic hyperplasia is prescribed tamsulosin (Flomax), which relaxes the prostatic smooth muscle and the iris dilator muscle. This medication targets the same receptor as which of the following?', o: ['Atropine', 'Isoproterenol', 'Propranolol', 'Phentolamine', 'Nicotine'], a: 3, ex: 'Tamsulosin is an α1-adrenergic antagonist (blocking α1 on bladder neck/prostate and iris radial muscle → intraoperative floppy iris). Phentolamine is also an α-adrenergic antagonist.' },
    { id: 'A23', src: 'AC77 · AC78', q: 'A 20-year-old engineer presents with fever (40 °C), blood pressure 70/50 mmHg, and heart rate 90 bpm. The doctor administers intravenous norepinephrine. What is the main purpose of this decision?', o: ['Activation of β-2 adrenergic receptor', 'Activation of α-2 adrenergic receptor', 'Activation of β-1 adrenergic receptor', 'Activation of α-1 adrenergic receptor', 'Activation of muscarinic acetylcholine receptor'], a: 3, ex: 'In vasodilatory/septic shock with severe hypotension, IV norepinephrine is given primarily to activate vascular α1-adrenergic receptors, causing vasoconstriction to restore blood pressure.' },
    { id: 'A24', src: 'AC76', q: 'A patient comes to the ER with low blood pressure. Which medication should be used to raise blood pressure?', o: ['Atropine', 'Muscarine', 'Propranolol', 'Methoxamine', 'Albuterol'], a: 3, ex: 'Methoxamine is a selective α1-adrenergic agonist that constricts arterioles to increase total peripheral resistance and blood pressure. Albuterol (β2) and muscarine lower BP; propranolol lowers CO/BP.' },
    { id: 'A25', src: 'AC76', q: 'Dobutamine is used to treat cardiogenic shock and severe heart failure. Its direct cardiac effects would be blocked by which of the following agents?', o: ['Methoxamine', 'Phentolamine', 'Metoprolol', 'Terbutaline', 'Hexamethonium'], a: 2, ex: 'Dobutamine stimulates cardiac β1 receptors to increase contractility and output. Metoprolol is a selective β1 antagonist that directly blocks these cardiac effects.' },
    { id: 'A26', src: 'AC77', q: 'A 57-year-old woman complains of a “panic attack” with a pounding heart and a heart rate of 130 bpm. Prescription of which drug relieves her tachycardia?', o: ['β-1 receptor antagonist', 'α-2 receptor agonist', 'β-2 receptor antagonist', 'α-1 receptor antagonist', 'Muscarinic receptor antagonist'], a: 0, ex: 'Cardiac pacemaker rate and contractility are driven by sympathetic β1 receptors, so a β1 receptor antagonist directly reduces tachycardia.' },
    { id: 'A27', src: 'AC78', q: 'A woman with hypertension is treated with drug “W”. Her blood pressure and heart rate decrease, but she develops diarrhea and moderate dehydration attributed to drug “W”. What is drug “W”?', o: ['Phentolamine', 'Propranolol', 'Isoproterenol', 'Terbutaline', 'Atropine'], a: 1, ex: 'Propranolol (non-selective β1/β2 antagonist) lowers HR and BP by blocking cardiac β1 receptors and can increase GI motility/cause diarrhea by blocking inhibitory β2 receptors in the gut. Phentolamine would not decrease HR.' },
    { id: 'A28', src: 'AC77 · AC78', q: 'In an experiment on an eye whose nerves were cut, control pupil size is 5 mm, light exposure gives 5 mm, and administering drug A widens the pupil to 8 mm. Which of the following is most likely drug A?', o: ['Phentolamine', 'Hexamethonium', 'Atropine', 'Neostigmine', 'Muscarine'], a: 2, ex: 'Among the choices listed, only atropine (muscarinic antagonist) causes mydriasis by blocking the iris sphincter; phentolamine (α-blocker), neostigmine (AChE inhibitor) and muscarine cause miosis, and hexamethonium blocks ganglia.', flag: 'Strictly, if all postganglionic parasympathetic nerves to the iris were severed (zero ACh release), atropine would not dilate the pupil and an α1 agonist would be required. The recall likely simplified an afferent/preganglionic cut or simply tests which option produces mydriasis.' }
  ]);
  CVS.after('G-C1', [
    { id: 'G1', src: 'AC73 · AC77', q: 'A 20-year-old man is stabbed in the lateral left side of the neck. Afterwards he has left facial dryness and cannot open his left eye widely. What else would you find on physical examination?', o: ['Mydriasis', 'Enophthalmos', 'Mouth dryness', 'Facial arteries constriction', 'Imprecise nictitating membrane'], a: 1, ex: 'Neck sympathetic chain injury produces Horner syndrome: ptosis, miosis, anhidrosis and apparent enophthalmos (plus facial vasodilation, not constriction). Humans lack a functional nictitating membrane.' },
    { id: 'G2', src: 'AC75 · AC77', core: true, q: 'A 55-year-old woman (55-pack-year smoker) has intermittent pain in her left shoulder and forearm with hand weakness. Chest CT reveals a large tumor in the left lung apex. What would you find on physical examination?', o: ['Dilation of the pupils', 'Facial anhidrosis', 'Facial arteries constriction', 'Imprecise nictitating membrane', 'Bulging of eyeballs out of the orbit'], a: 1, ex: 'A Pancoast tumor at the lung apex compresses the 2nd-order (preganglionic) sympathetic fibers ascending over the apex, causing Horner syndrome: miosis, ptosis, enophthalmos and ipsilateral facial anhidrosis.' }
  ]);
  CVS.after('G-C2', [
    { id: 'G5', src: 'AC76 · AC77', core: true, q: 'In a patient with a left-eye preganglionic (2nd-order) Horner syndrome tested with cocaine and Paredrine (hydroxyamphetamine), which result is expected in the left eye?', o: ['Cocaine: no change, Paredrine: mydriasis', 'Cocaine: no change, Paredrine: miosis', 'Cocaine: no change, Paredrine: no change', 'Cocaine: miosis, Paredrine: mydriasis', 'Cocaine: mydriasis, Paredrine: no change'], a: 0, ex: 'Cocaine blocks NE reuptake, so without sympathetic firing no NE is released → no change in any Horner lesion. Paredrine releases stored NE from intact postganglionic terminals; in a preganglionic lesion those terminals are still intact → mydriasis.' },
    { id: 'G6', src: 'AC78', core: true, q: 'A patient has a left carotid artery tumor causing left-sided Horner syndrome. What happens to the left pupil after cocaine and Paredrine (hydroxyamphetamine) eye drops?', o: ['Cocaine: miosis, Paredrine: no change', 'Cocaine: no change, Paredrine: no change', 'Cocaine: no change, Paredrine: mydriasis', 'Cocaine: no change, Paredrine: miosis', 'Cocaine: mydriasis, Paredrine: no change'], a: 1, ex: 'A carotid artery tumor damages the 3rd-order (postganglionic) sympathetic fibers. Cocaine fails (no NE release → no change), and Paredrine also fails because the degenerated postganglionic terminals have no stored NE left to release → no change.' }
  ]);
  CVS.after('G-C3', [
    { id: 'G7', src: 'AC75 · AC76', q: 'A 20-year-old woman complains of episodic cyanosis of her fingers in response to cold or stress. Prazosin reduces peripheral vasoconstriction and relieves her pain. What type of drug is prazosin?', o: ['Ganglionic drug', 'Sympatholytic drug', 'Sympathomimetic drug', 'Parasympatholytic drug', 'Parasympathomimetic drug'], a: 1, ex: 'Prazosin is a selective α1-adrenergic antagonist that blocks sympathetic vasoconstriction in digital arteries; drugs that inhibit sympathetic effects are sympatholytic.' },
    { id: 'G8', src: 'AC75 · AC76 · AC77', core: true, q: 'A 35-year-old woman has severe Raynaud phenomenon (cold- and emotion-induced digital vasospasm) requiring surgical sympathectomy. Which nerve fiber is the most appropriate site for denervation?', o: ['Superior cervical ganglion', 'Postganglionic sympathetic fiber', 'Preganglionic sympathetic fiber', 'Dorsal root ganglion', 'Vagus nerve'], a: 2, ex: 'Preganglionic sympathetic denervation is preferred over postganglionic denervation because cutting postganglionic fibers causes severe denervation supersensitivity (α1 receptor up-regulation), making digital vessels hyper-responsive to circulating catecholamines and cold.' },
    { id: 'G9', src: 'AC73', q: 'A 35-year-old woman with digital necrosis from cold undergoes postganglionic sympathectomy and subsequently develops hypersensitivity to cold. What causes this hypersensitivity?', o: ['Degeneration of preganglionic fiber', 'Degeneration of postganglionic fiber', 'Up-regulation of receptors', 'Down-regulation of receptors', 'Hyperactivation of sympathetic nervous system'], a: 2, ex: 'Loss of postganglionic nerve terminals eliminates baseline NE exposure, inducing compensatory up-regulation of postsynaptic α1-adrenergic receptors on vascular smooth muscle (denervation supersensitivity).', flag: 'The AC79 recall key listed both B and C (noting postganglionic degeneration occurs first, followed by receptor up-regulation), while AC73 keyed C directly.' },
    { id: 'G10', src: 'AC73', q: 'Which of the following drugs can relieve the cold hypersensitivity that develops after postganglionic sympathectomy in Raynaud phenomenon?', o: ['α-1 antagonist', 'α-2 agonist', 'β-1 agonist', 'β-2 antagonist', 'Muscarinic agonist'], a: 0, ex: 'An α1-adrenergic antagonist directly blocks the up-regulated postsynaptic α1 receptors on digital arterioles, preventing vasoconstriction by circulating catecholamines.' }
  ]);
  CVS.after('G-C4', [
    { id: 'G13', src: 'AC76 · AC77', core: true, q: 'A medical student conducts a rabbit experiment: (I) cuts the preganglionic cervical sympathetic trunk, (II) applies 1% v/v nicotine to the superior cervical ganglion, and (III) stimulates the peripheral (distal) preganglionic fiber. After step III, what result should be expected?', o: ['Exophthalmos', 'Mydriasis', 'Narrower palpebral fissure', 'Imprecise nictitating membrane', 'Generalized vasoconstriction'], a: 2, ex: 'High-concentration (1%) nicotine causes persistent depolarization block of the nicotinic receptors in the superior cervical ganglion. Stimulating the preganglionic fiber therefore fails to cross the ganglion, so Horner-like sympathetic loss persists (miosis, narrower palpebral fissure, enophthalmos, prominent nictitating membrane).', flag: 'The AC76 variant replaced option C/D with “Larger palpebral fissure” and “Precise [i.e., prominent/protruding] nictitating membrane”, keying D for the same Horner-persistence mechanism.' }
  ]);
  CVS.after('G-C5', [
    { id: 'G15', src: 'AC75 · AC76', core: true, q: 'In a dog ANS experiment, control values are BP 100/60 mmHg, HR 90/min, pupil 1.5 mm, GI motility 10/min. After substance Q: BP 110/70, HR 105, pupil 2.0 mm, GI motility 0. Giving acetylcholine after Q produces no further change (BP 110/70, HR 105, pupil 2.0 mm, GI motility 0). What is substance Q?', o: ['Atropine', 'Phentolamine', 'Isoproterenol', 'Propranolol', 'Hexamethonium'], a: 0, ex: 'Substance Q increases HR (blocks vagal M2), dilates the pupil (blocks iris sphincter M3), abolishes GI motility (blocks M3), and completely blocks subsequent acetylcholine — classic muscarinic blockade by atropine.' },
    { id: 'G16', src: 'AC75 · AC76', q: 'In the dog experiment where atropine (substance Q) increases HR from 90 to 105/min and BP from 100/60 to 110/70 mmHg, why does blood pressure increase?', o: ['Direct effect regulating blood pressure', 'Baroreflex following blood flow in carotid body', 'Up-regulation of receptors at cardiac muscle', 'Indirect effect following increased heart rate', 'Down-regulation of receptors at local blood vessel'], a: 3, ex: 'Systemic blood vessels lack significant parasympathetic vasoconstrictor innervation. Atropine blocks vagal M2 receptors on the SA node to raise heart rate and cardiac output, raising BP indirectly.' },
    { id: 'G17', src: 'AC73 · AC77', core: true, q: 'A dog is injected intravenously with drug A. Blood pressure drops, pupil diameter decreases, and gastrointestinal motility increases, while heart rate remains unchanged. What is drug A?', o: ['Atropine', 'Muscarine', 'Acetylcholine', 'Methacholine', 'Phentolamine'], a: 4, ex: 'Phentolamine blocks α1 receptors (vasodilation → BP ↓; iris dilator relaxes → miosis) and α2 receptors (removes sympathetic inhibition of the dog gut → GI motility ↑) without directly blocking cardiac β1 receptors (HR unchanged in the lab table). Muscarinic agonists would also drop HR.' },
    { id: 'G18', src: 'AC73 · AC77 · AC78', q: 'In a dog experiment, control is BP 100/60, HR 100, pupil 1.5 mm, GI 10/min. After substance Y (phentolamine): BP 90/50, HR 100, pupil 1.0 mm, GI 12/min. After NE + Y: BP 100/70, HR 120, pupil 1.0 mm, GI 12/min. Why does BP decrease after administering substance Y?', o: ['Direct effect regulating blood pressure', 'Up-regulation of receptors in cardiac muscle', 'Indirect effect following an increase of heart rate', 'Down-regulation of receptors in local blood vessels', 'Baroreceptor reflex after increasing of blood flow in carotid body'], a: 0, ex: 'Phentolamine directly blocks vascular α1-adrenergic receptors, causing arteriolar vasodilation and a direct drop in blood pressure while HR stays at 100. (When NE is added later, α1 is still blocked so BP rises back to 100/70 only indirectly via β1-driven HR 120.)', flag: 'AC73 and AC79 student keys erroneously chose D (“down-regulation of receptors”), confusing acute competitive α1 blockade with chronic receptor down-regulation; AC77–78 correctly keyed A.' },
    { id: 'G19', src: 'AC76 · AC77 · AC78', q: 'In a dog experiment, control is BP 100/60, HR 90, pupil 1.5, GI 10. Epinephrine alone gives BP 130/85, HR 105, pupil 2.0, GI 0. Epinephrine in the presence of propranolol gives BP 110/70, HR 90, pupil 2.0, GI 0. Why does epinephrine alone produce a more dramatic BP rise compared with epinephrine plus propranolol?', o: ['Direct effect regulating blood pressure', 'Component of blood pressure increase following parasympathetic nervous system', 'Up-regulation of receptors at cardiac muscle', 'Component of blood pressure increase following heart rate', 'Down-regulation of receptors at local blood vessel'], a: 3, ex: 'Propranolol blocks β1 receptors, keeping HR at 90 so BP rises only modestly to 110/70 (via vascular α1). With epinephrine alone, unblocked β1 stimulation raises HR to 105 (and cardiac output), adding a cardiac/HR component that pushes BP to 130/85.', flag: 'AC77–78 keyed D (explaining the extra BP rise of Epi alone vs Epi + propranolol), whereas AC76 and AC79 student keys listed A (explaining why Epi + propranolol still raised BP slightly above control via α1).' },
    { id: 'G20', src: 'AC76', core: true, q: 'Drug X causes an increase in blood pressure and a decrease in heart rate when administered intravenously. If an antagonist at ganglionic nicotinic receptors is administered first, drug X causes an increase in blood pressure and an increase in heart rate. Which of the following is most likely drug X?', o: ['Propranolol', 'Norepinephrine', 'Isoproterenol', 'Terbutaline', 'Tubocurarine'], a: 1, ex: 'Norepinephrine strongly activates vascular α1 (↑↑BP) and cardiac β1 (direct ↑HR). Normally, the large BP rise triggers a baroreceptor-mediated vagal reflex that overrides β1 and causes reflex bradycardia (↓HR). A ganglionic blocker abolishes the vagal reflex arc, unmasking NE’s direct β1-mediated tachycardia (↑HR).', flag: 'The AC76 student key erroneously listed A (Propranolol), which neither raises BP nor increases HR after ganglion blockade. AC79 correctly keyed B (Norepinephrine).' }
  ]);
  CVS.after('S-C1', [
    { id: 'S2', src: 'AC75 · AC76 · AC77', q: 'Which of the following properties of sound indicates loudness?', o: ['Hertz', 'Velocity', 'Amplitude', 'Frequency', 'Phase'], a: 2, ex: 'Perceived loudness corresponds to wave amplitude (sound pressure/intensity). Frequency determines pitch, and Hertz is the unit of frequency.', flag: 'The AC75 and AC76 recall keys had transcription errors (listing Frequency and Phase respectively); AC77 and AC79 correctly key Amplitude.' },
    { id: 'S3', src: 'AC77 · AC78', q: 'Which property of sound determines pitch (เสียงแหลม-ทุ้ม / ความสูง-ต่ำ)?', o: ['Frequency', 'Amplitude', 'Phase', 'Velocity', 'Hertz'], a: 0, ex: 'Pitch (high/low tone) is determined by the frequency of the sound wave. Hertz is the unit used to measure frequency, not the physical property itself.' },
    { id: 'S4', src: 'AC76 · AC77 · AC78', core: true, q: 'A sound wave takes 500 ms to complete one cycle. What is its frequency?', o: ['2 Hz', '5 Hz', '20 Hz', '50 Hz', '200 Hz'], a: 0, ex: 'Convert period to seconds first: T = 500 ms = 0.5 s. Then f = 1 / T = 1 / 0.5 = 2 Hz.' },
    { id: 'S5', src: 'AC73–79', q: 'A sound wave takes 2.5 ms to complete one cycle. What is its frequency?', o: ['2.5 Hz', '0.0025 Hz', '0.4 Hz', '40 Hz', '400 Hz'], a: 4, ex: 'T = 2.5 ms = 0.0025 s. f = 1 / T = 1 / 0.0025 = 1000 / 2.5 = 400 Hz.' }
  ]);
  CVS.after('S-C2', [
    { id: 'S6', src: 'AC75', core: true, q: 'A 1000 Hz sound measures 20 dB SPL. Given that the normal human hearing threshold at 1000 Hz is 7.5 dB SPL, what is this level in dB HL?', o: ['0', '7.5', '12.5', '20', '27.5'], a: 2, ex: 'dB HL = dB SPL − RETSPL (normal threshold at that frequency) = 20 − 7.5 = 12.5 dB HL.' },
    { id: 'S7', src: 'AC75 · AC77', core: true, q: 'A sound has a pressure of 2,000 μPa (v = 341 m/s at 25 °C; normal threshold at 1000 Hz = 7.5 dB SPL). What is its level in dB SPL?', o: ['2 dB SPL', '20 dB SPL', '40 dB SPL', '66 dB SPL', '400 dB SPL'], a: 2, ex: 'Reference pressure for 0 dB SPL is 20 μPa. dB SPL = 20 log₁₀(P / 20 μPa) = 20 log₁₀(2000 / 20) = 20 log₁₀(100) = 20 × 2 = 40 dB SPL.', flag: 'The AC77 recall printed “dB SL” in the choices by typo instead of “dB SPL”; AC75 and AC79 have “dB SPL”.' },
    { id: 'S8', src: 'AC76 · AC77', core: true, q: 'A 70 dB SPL sound at 1000 Hz is presented to a patient whose hearing threshold at 1000 Hz is 40 dB SPL (normal human threshold is 7.5 dB SPL). How many dB SL does the patient hear?', o: ['30', '40', '47.5', '77.5', '110'], a: 0, ex: 'Sensation level (dB SL) is referenced to the individual patient’s own threshold, NOT the normal threshold: dB SL = 70 − 40 = 30 dB SL. (AC76 tested the same formula in dB HL: 90 dB HL presented − 60 dB HL patient threshold = 30 dB SL.)' }
  ]);
  CVS.after('S-C3', [
    { id: 'S10', src: 'AC76', core: true, q: 'Which of the following properties of sound allow humans to sense the direction of a sound source?', o: ['Frequency and Amplitude', 'Amplitude and Phase', 'Frequency and Phase', 'Phase and Impedance', 'Resonance and Impedance'], a: 1, ex: 'By Rayleigh’s duplex theory, humans localize sound using interaural level (amplitude) differences (ILD, via head shadow at high frequencies) and interaural time/phase differences (ITD/IPD, at low frequencies).', flag: 'The AC79 recall key erroneously chose “Frequency and Phase”; AC76 correctly keys “Amplitude and Phase” (both ears receive the same frequency — frequency only determines which cue dominates).' },
    { t: 'open', id: 'S11', src: 'AC75 · AC76 · AC78', q: 'In a hearing test on a giant, a 1000 Hz sound presented at the right ear takes 0.02 s to reach the left ear (speed of sound v = 341 m/s at 25 °C; normal threshold 7.5 dB SPL). Assuming head width equals the ear-to-ear distance, what is the width of the giant’s head?', ans: '<b>6.82 m</b> — distance s = v × t = 341 m/s × 0.02 s = 6.82 m. (The 1000 Hz and 7.5 dB SPL values are distractors.)' }
  ]);
  CVS.after('S-C4', [
    { id: 'S16', src: 'AC76', core: true, q: 'If a tympanic membrane has a total area of 85 mm² but an effective vibrating area of 55 mm², and sound is transmitted to the oval window via a stapes footplate of 3.2 mm², how many fold does the hydraulic principle amplify sound pressure?', o: ['26.5', '2.5', '1.5', '17', '0.6'], a: 3, ex: 'Since F₁ = F₂, pressure ratio P₂ / P₁ = A₁ / A₂ using the effective vibrating area of the drum (55 mm², not total 85 mm²): 55 ÷ 3.2 ≈ 17.2 ≈ 17-fold (≈ 24.6 dB).' },
    { t: 'open', id: 'S17', src: 'AC73–79', q: 'A 20 dB SPL sound enters a device with hydraulic amplification (increasing sound pressure 17-fold). What is the output sound level in dB SPL?', ans: '<b>44.6 dB SPL</b> — pressure gain = 20 log₁₀(17) ≈ 24.6 dB; output = 20 + 24.6 = 44.6 dB SPL.', flag: 'The AC79 recall key printed “20 log(17) = 22.6” and “44.6 dB HL” by typo; 20 log₁₀(17) = 24.61 dB, giving 20 + 24.6 = 44.6 dB SPL.' }
  ]);
  CVS.after('W-C1', [
    { id: 'W2', src: 'AC75 · AC76', core: true, q: 'Which of the following statements is INCORRECT about light scattering?', o: ['It occurs when light passes through an irregular/inhomogeneous medium', 'Shorter-wavelength light scatters more than longer-wavelength light', 'Longer-wavelength light scatters more than shorter-wavelength light', 'It can occur in patients with cataracts', 'The sky looks blue because short-wavelength blue light scatters into our eyes'], a: 2, ex: 'Rayleigh scattering is inversely proportional to λ⁴: shorter wavelengths (blue/violet) scatter much more strongly than longer wavelengths (red). Cataract opacities also scatter light, causing glare.' },
    { id: 'W3', src: 'AC75 · AC76 · AC78', core: true, q: 'Which property of light is used in making anti-reflective / anti-glare glasses (กระจกตัดแสง)?', o: ['Diffraction', 'Refraction', 'Interference', 'Scattering', 'Glare'], a: 2, ex: 'Anti-reflective lens coatings (and interference-filter car films) use thin-film destructive interference so light reflected from the front and back coating surfaces cancels out.', flag: 'The AC79 recall key erroneously listed Scattering; AC75, AC76 and AC78 all correctly key Interference.' },
    { id: 'W4', src: 'AC76', q: 'Arrange the following electromagnetic waves from LOW to HIGH wavelength:', o: ['Infrared &lt; ultraviolet &lt; X-rays', 'Ultraviolet &lt; visible light &lt; infrared', 'Infrared &lt; visible light &lt; ultraviolet', 'Gamma-ray &lt; visible light &lt; X-ray'], a: 1, ex: 'From shortest to longest wavelength: gamma rays &lt; X-rays &lt; ultraviolet &lt; visible light (400–700 nm) &lt; infrared &lt; microwaves &lt; radio waves.' },
    { id: 'W5', src: 'AC78', core: true, q: 'Which of the following correctly orders electromagnetic waves from HIGH to LOW frequency?', o: ['Infrared &gt; visible light &gt; UV &gt; X-ray', 'UV &gt; visible light &gt; Infrared &gt; X-ray', 'X-ray &gt; UV &gt; visible light &gt; Infrared', 'UV &gt; X-ray &gt; visible light &gt; Infrared'], a: 2, ex: 'Since c = λν and E = hν, shorter wavelength means higher frequency and higher photon energy: X-ray &gt; UV &gt; visible light &gt; infrared.' },
    { id: 'W6', src: 'AC77', q: 'Which of the following is NOT a physical property of light?', o: ['Scattering', 'Diffusion', 'Diffraction', 'Refraction', 'Interference'], a: 1, ex: 'Refraction, diffraction, interference and scattering are optical properties of light; diffusion is net passive movement of molecules down a concentration gradient.' },
    { id: 'W7', src: 'AC76', q: 'Which of the following statements about wave optics is INCORRECT?', o: ['Constructive interference is the cancellation of wavefronts', 'Unpolarized light consists of light polarized in different planes', 'Destructive interference occurs when wavefronts cancel each other', 'Diffraction is used in multifocal lenses', 'Car window film uses an interference filter'], a: 0, ex: 'Constructive interference adds/reinforces waves in phase; cancellation of wavefronts is destructive interference. All four other statements are true.', flag: 'Option A was recalled as “Instructive” — a transcription typo for “Constructive”.' },
    { id: 'W8', src: 'AC76 · AC77', core: true, q: 'Which of the following statements is INCORRECT regarding geometrical optics?', o: ['Vergence of a convex lens is positive (+)', 'Vergence of a concave lens is negative (−)', 'Vergence of object distance is always negative (−)', 'A convex lens converges light', 'A concave lens diverges light'], a: 2, ex: 'In U + P = V, object vergence U = −1/s is negative for a real object in front of a lens (diverging rays), but U is POSITIVE (+) for a virtual object (converging rays aimed behind the lens, as in multi-lens systems). Thus it is not “always” negative.', flag: 'AC76 recall accidentally typed “ถูกต้อง (correct)” in the stem instead of “ผิด (incorrect)”; AC77 and AC79 confirm the stem asks which is incorrect.' }
  ]);
  CVS.after('W-C2', [
    { id: 'W10', src: 'AC77', core: true, q: 'Which of the following is NOT a property of laser light?', o: ['Monochromaticity', 'Coherence', 'Directionality', 'Ionizing', 'High intensity'], a: 3, ex: 'Lasers emit non-ionizing optical radiation (UV, visible or infrared) characterized by monochromaticity, coherence, directionality, polarization and high intensity. Ionizing radiation belongs to X-rays and gamma rays.' }
  ]);
  CVS.after('W-C3', [
    { id: 'W13', src: 'AC76 · AC77', core: true, q: 'Which of the following statements is INCORRECT?', o: ['Excimer laser produces photoablation', 'Femtosecond laser is used in cataract surgery via photodisruption', 'Nd:YAG laser produces photoablation', 'Shorter-wavelength light scatters more than longer-wavelength light', 'None of the above is incorrect'], a: 2, ex: 'Nd:YAG laser (near-infrared, 1064 nm) acts in ophthalmology by photodisruption (high pulse energy plasma shock wave), NOT photoablation (which requires UV photons like the 193 nm excimer laser) and NOT photocoagulation.' }
  ]);
  CVS.after('W-C4', [
    { id: 'W16', src: 'AC78', q: 'Which of the following is the most common visual disorder in the elderly?', o: ['Presbyopia', 'Amblyopia', 'Asthenopia', 'Hemianopia', 'Diplopia'], a: 0, ex: 'Presbyopia (age-related loss of lens elasticity and accommodation, impairing near focus) affects virtually all older adults. Amblyopia = lazy eye; asthenopia = eye strain; hemianopia = half-field loss; diplopia = double vision.' },
    { id: 'W17', src: 'AC78', core: true, q: 'Which of the following statements is INCORRECT about myopia?', o: ['Commonly occurs in aphakia (absence of the crystalline lens)', 'May occur together with astigmatism', 'Occurs when the refractive power of the lens is too high', 'Occurs when the axial length of the eyeball is too long'], a: 0, ex: 'Myopia focuses images in front of the retina due to excessive axial length or too much refractive power, and may coexist with astigmatism. Aphakia (missing lens) removes ~20 D of converging power and causes severe HYPEROPIA, not myopia.' },
    { id: 'W18', src: 'AC73–79', core: true, q: 'Which of the following statements is INCORRECT about refractive errors?', o: ['A concave lens corrects myopia', 'A convex lens corrects hyperopia', 'A cylindrical lens corrects astigmatism', 'A concave lens corrects presbyopia', 'Astigmatism can occur alone or together with myopia or hyperopia'], a: 3, ex: 'Presbyopia is a loss of near-focusing power (accommodation), so it is corrected with a CONVEX (+) reading lens (or the convex lower near-add segment of a bifocal/progressive lens), NOT a concave lens.' }
  ]);
  CVS.after('V-C2', [
    { id: 'V2', src: 'AC70', q: 'What type(s) of joint is/are found in vertebrae?', o: ['Synovial joint', 'Cartilaginous joint', 'Fibrous joint', 'Synovial and fibrous joint', 'Synovial and cartilaginous joint'], a: 4, ex: 'Adjacent vertebral bodies meet at secondary cartilaginous joints (symphyses via intervertebral discs), while the articular processes form plane synovial facet (zygapophyseal) joints. Both synovial and cartilaginous joints are present.', flag: 'AC76–78 recall booklet miskeyed B (cartilaginous only); AC70 yellow key correctly marks E.' },
    { id: 'V3', src: 'AC74 · AC79', core: true, q: 'Which structures have to be cut to perform a posterior spinal cord operation (to expose the spinal cord posteriorly)?', o: ['Pedicle, spinous process, lamina', 'Lamina, ligamentum flavum, spinous process', 'Pedicle, spinous process, ligamentum flavum', 'Spinous process, lamina, posterior longitudinal ligament', 'Ligamentum flavum, posterior longitudinal ligament, lamina'], a: 1, ex: 'In a posterior approach (laminectomy), the surgeon removes the spinous process and laminae along with the ligamentum flavum joining adjacent laminae to open the roof of the vertebral canal. Pedicles form the lateral walls and the PLL lies in front of the cord.' }
  ]);
  CVS.after('V-C3', [
    { id: 'V7', src: 'AC68 · AC73 · AC76', core: true, q: 'ข้อใดไม่ใช่ลักษณะของ thoracic spine (Which is not a feature of the thoracic spine?)', o: ['Mammillary process', 'Small vertebral canal', 'Long spinous process', 'Facets for head and tubercle of ribs', 'Superior facets face posteriorly'], a: 0, ex: 'The mammillary process (on the back of the superior articular process) is a hallmark of lumbar vertebrae, not thoracic. Thoracic vertebrae have a small circular canal, long downward-sloping spinous processes, costal facets for rib heads and tubercles, and superior facets facing posteriorly.' },
    { id: 'V8', src: 'AC75', q: 'Which of the following is subjected to synovitis?', o: ['Epiphyseal plate', 'Uncovertebral joint', 'Pubic symphysis', 'Radioulnar syndesmosis', 'Suture'], a: 1, ex: 'Synovitis occurs in synovial joints. Among the choices, only the uncovertebral joints (joints of Luschka between C3–C7 uncinate processes) are classified as small synovial (or synovial-like) joints; epiphyseal plates and pubic symphysis are cartilaginous, while syndesmoses and sutures are fibrous.' }
  ]);
  CVS.after('V-C4', [
    { id: 'V11', src: 'AC70', core: true, q: 'Lumbar herniated disc พบทิศทางใดมากที่สุด (In which direction does a lumbar intervertebral disc most commonly herniate?)', o: ['Posterior', 'Posterolateral', 'Lateral', 'Anterolateral', 'Anterior'], a: 1, ex: 'The nucleus pulposus sits slightly posterior to the disc centre, and the posterior longitudinal ligament reinforces the midline posteriorly. Herniation therefore pushes posterolaterally, where the annulus fibrosus is thinner and unsupported, compressing the traversing nerve root.' },
    { id: 'V12', src: 'AC72 · AC74', q: 'Which ligament does not support the spinal column?', o: ['Posterior longitudinal ligament', 'Anterior longitudinal ligament', 'Sacrospinous ligament', 'Supraspinous ligament', 'Interspinous ligament'], a: 2, ex: 'The sacrospinous ligament connects the sacrum to the ischial spine in the pelvis (forming the greater and lesser sciatic foramina), rather than joining vertebrae. ALL, PLL, supraspinous and interspinous ligaments all support the vertebral column.' },
    { id: 'V13', src: 'AC77', q: 'Which choice is INCORRECT about ligaments of the deep back?', o: ['The posterior longitudinal ligament is thinner than its anterior counterpart.', 'The interspinous ligament is stronger than the supraspinous ligament.', 'The ligamentum flavum connects adjacent laminae.', 'The supraspinous ligament connects adjacent spinous processes.', 'The ligamentum nuchae connects the cervical spinous processes.'], a: 1, ex: 'The interspinous ligament is a thin, weak membrane between adjacent spinous processes—weaker than the thick cord-like supraspinous ligament along their tips. All other statements accurately describe the spinal ligaments.' }
  ]);
  CVS.after('V-C5', [
    { id: 'V15', src: 'AC70 · AC75', q: 'กล้ามเนื้อที่ไม่ได้เกาะ transverse process (Which muscle does not attach to the transverse process?)', o: ['Rotatores', 'Multifidus', 'Semispinalis', 'Spinalis', 'Longissimus'], a: 3, ex: 'Spinalis (the medial column of erector spinae) runs strictly from spinous process to spinous process. Longissimus attaches to transverse processes, and the transversospinal muscles (semispinalis, multifidus, rotatores) all arise from transverse processes.' },
    { id: 'V16', src: 'AC76', q: 'What is the muscle that arises from a transverse process and inserts into a spinous process 1 vertebra superiorly?', o: ['Semispinalis muscle', 'Spinalis muscle', 'Multifidus muscle', 'Rotatores muscle', 'Splenius muscle'], a: 3, ex: 'In the transversospinal group, fibres span fewer segments as they go deeper: semispinalis spans 4–6 levels, multifidus 2–4 levels, and rotatores 1–2 levels (rotatores breves span 1 segment, longi span 2).' }
  ]);
  CVS.after('I-C1', [
    { id: 'I2', src: 'AC76', core: true, q: 'What is the normal distance between the dens of axis and the anterior arch of atlas (atlanto-dental interval)?', o: ['Less than 3 mm', 'Less than 5 mm', 'Less than 7 mm', 'Less than vertebral height', 'Less than 50% of vertebral height'], a: 0, ex: 'On a lateral cervical radiograph, the normal atlanto-dental interval (ADI) between the anterior arch of C1 and the dens of C2 is less than 3 mm in adults (and less than 5 mm in children). Widening indicates transverse ligament injury or C1–C2 instability.', flag: 'Assumes an adult patient (&lt; 3 mm in adults; &lt; 5 mm in children).' },
    { id: 'I3', src: 'AC78', q: 'On this lateral plain film of the atlantoaxial joint, which structure is the posterior arch of the atlas (C1)?', fig: CVS.fig('ac78-atlas', 'AC78: lateral C1–C2 radiograph with anterior arch (A), dens (B), C2 body (C), and posterior arch (green).', 'ac78', 3), o: ['A', 'B', 'C', 'D (green)'], a: 3, ex: 'A (yellow) is the anterior arch of C1, B (red) is the dens of C2, C (blue) is the body of C2, and the green dotted ring posteriorly is the posterior arch of the atlas (C1), sitting just above the C2 spinous process (pink).' }
  ]);
  CVS.after('I-C2', [
    { id: 'I7', src: 'AC71', q: 'Normal alignment lines of the cervical spine include all of the following EXCEPT:', o: ['Atlantoaxial line', 'Anterior vertebral line', 'Posterior vertebral line', 'Spinolaminar line', 'Posterior spinous line'], a: 0, ex: 'On a lateral cervical film, alignment is checked along four smooth curves: anterior vertebral line, posterior vertebral line, spinolaminar line, and posterior spinous (interspinous) line. There is no “atlantoaxial line.”' },
    { id: 'I8', src: 'AC76', core: true, q: 'Which view is the most appropriate view to evaluate the neural foramina of C-spines?', o: ['PA view', 'Lateral view', 'Flexion view', 'Oblique view', 'Extension view'], a: 3, ex: 'Cervical neural (intervertebral) foramina face anterolaterally at roughly 45°, so they are seen clearly only on the oblique view. By contrast, thoracic and lumbar neural foramina face laterally and are best seen on the lateral view.' },
    { id: 'I9', src: 'AC79', q: 'What is not seen well in a lateral radiograph of the vertebral column?', o: ['Intervertebral foramen', 'Pedicle', 'Spinous process', 'Transverse process', 'Vertebral body'], a: 3, ex: 'Transverse processes project laterally and overlap the vertebral body/pedicles end-on on a lateral film, so they are best seen on an AP view. Vertebral bodies, pedicles, spinous processes, and (in lumbar/thoracic) intervertebral foramina are well seen laterally.' }
  ]);
  CVS.after('I-C3', [
    { id: 'I13', src: 'AC71 · AC72', q: 'เทียบ Scotty dog กับ anatomy ข้อใดผิด (Which Scotty dog–anatomy pairing is incorrect?)', o: ['Eye = pedicle', 'Ear = superior articular process', 'เท้าหน้า (Front leg) = inferior articular process', 'Neck = pars interarticularis', 'Nose = spinous process'], a: 4, ex: 'On the lumbar oblique view, the nose of the Scotty dog is the transverse process, not the spinous process. Eye = pedicle, ear = superior articular process, neck = pars interarticularis, front leg = inferior articular process.' },
    { id: 'I14', src: 'AC78', q: 'If a doctor wants to observe a pars interarticularis defect, which view in plain film is most suitable?', o: ['Anteroposterior view', 'Oblique view', 'Normal lateral view', 'Open-mouth view'], a: 1, ex: 'A pars interarticularis defect (spondylolysis) appears as a “collar” or break across the neck of the Scotty dog on the lumbar oblique view.' },
    { id: 'I15', src: 'AC79', q: 'On this lateral lumbar radiograph, which arrow points at the pars interarticularis?', fig: CVS.fig('ac79-pars', 'AC79: lateral lumbar radiograph with five labelled arrows A–E.', 'ac79', 5), o: ['A', 'B', 'C', 'D', 'E'], a: 2, ex: 'C (blue) marks the narrow bridge of bone between the superior and inferior articular processes: the pars interarticularis. A = superior articular process, B = inferior articular process, D = pedicle, E = intervertebral foramen (red arrow = facet joint).' }
  ]);
  CVS.after('I-C4', [
    { id: 'I17', src: 'AC79', q: 'Which imaging technique is used here, and what vertebral level is shown?', fig: CVS.fig('ac79-ct', 'AC79: axial spinal scan with ribs articulating bilaterally.', 'ac79', 5), o: ['T1-MRI, thoracic', 'T1-MRI, lumbar', 'T2-MRI, thoracic', 'CT-scan, thoracic', 'CT-scan, lumbar'], a: 3, ex: 'Bright white cortical bone with crisp bony detail and low soft-tissue contrast identifies a bone-window CT scan (not MRI). Ribs articulating with the vertebral body and transverse processes identify the thoracic level.' }
  ]);
  CVS.after('I-C5', [
    { id: 'I19', src: 'AC68 · AC76', core: true, q: 'What is the modality of choice to diagnose intervertebral disc disease?', o: ['Plain radiograph', 'CT myelography', 'Computed tomography', 'MRI', 'Ultrasound'], a: 3, ex: 'MRI gives the best soft-tissue contrast without ionising radiation, making it the modality of choice for intervertebral discs, spinal cord, nerve roots, and bone marrow. Plain films and CT show bone best.' },
    { id: 'I20', src: 'AC70', q: 'What is the best modality to evaluate the nerve root of the cervical spine?', o: ['MRI', 'CT', 'Lateral plain radiograph', 'Oblique plain radiograph', 'AP plain radiograph'], a: 0, ex: 'While an oblique plain film shows the bony neural foramina, only MRI directly visualises the soft-tissue nerve roots and spinal cord.' },
    { id: 'I21', src: 'AC75', core: true, q: 'ผู้ป่วยเป็น lumbar herniated disc เป็นโรคหัวใจใส่ pacemaker ไว้จะตรวจด้วยเครื่องอะไร (A patient with a lumbar herniated disc has a cardiac pacemaker. Which imaging modality should be used?)', o: ['MRI', 'CT scan with myelography', 'Angiography', 'Ultrasound', 'Tc99m-MDP bone scintigraphy'], a: 1, ex: 'MRI is the first-line test for a herniated disc, but a cardiac pacemaker is a classic contraindication to MRI. When MRI cannot be performed, CT myelography (CT after intrathecal contrast) is the best alternative to outline disc herniation and nerve-root compression.', flag: 'AC76–78 recall booklet erroneously keyed E (bone scintigraphy); the correct clinical alternative to MRI for herniated disc is B (CT myelography).' }
  ]);
  CVS.after('C-C1', [
    { id: 'C3', src: 'AC70 · AC77', q: 'A male patient came to the hospital with a loss of sensation at the penis and scrotum after a car accident. Which nerve root is most likely to be affected?', o: ['T11–12', 'L2–3', 'L4–5', 'S2–3', 'S4–5'], a: 3, ex: 'Sensation to the perineum, penis, and scrotum is carried mainly by the pudendal nerve (S2–S4), mapped to the S2–S3 dermatomes on the lecture dermatome chart (S4–S5 is perianal).' },
    { id: 'C4', src: 'AC73 · AC78', q: 'A female patient has an injury at the T4 dermatome. Which cutaneous area is most likely to lose sensation?', o: ['Posterior forearm', 'Nipple', 'Shoulder', 'Umbilicus', 'Infraclavicular area'], a: 1, ex: 'Key trunk dermatome landmarks: T4 = nipple line, T7 = xiphoid process, T10 = umbilicus, T12/L1 = inguinal region.' }
  ]);
  CVS.after('C-C2', [
    { id: 'C9', src: 'AC68', q: 'ในผู้ป่วยมะเร็งที่มีการกดทับเส้นประสาท หากสงสัยว่ามะเร็งมีการ metastasis ไปกดทับที่ไขสันหลัง จะพบก้อนมะเร็งได้ที่บริเวณใด (In a cancer patient with suspected metastatic spinal cord compression, in which space is the mass most likely found?)', o: ['Epidural space', 'Subdural space', 'Arachnoid membrane', 'Subarachnoid space', 'Pia mater'], a: 0, ex: 'Over 95% of metastatic spinal cord compression occurs in the epidural (extradural) space, typically spreading from vertebral bodies or via the valveless internal vertebral venous plexus (Batson plexus) inside the epidural space.', flag: 'AC68 yellow key marked D (subarachnoid space), but metastatic spinal cord compression via Batson’s venous plexus/vertebrae is overwhelmingly epidural (A).' },
    { id: 'C10', src: 'AC70', q: 'What is inside the subdural space of the spinal cord?', o: ['Fat', 'CSF', 'Internal vertebral plexus', 'Anterior spinal artery', 'None'], a: 4, ex: 'The subdural space is a potential space containing only a capillary film of serous fluid—none of the structures listed. Fat and the internal vertebral venous plexus lie in the epidural space; CSF and the anterior spinal artery lie in the subarachnoid space.' },
    { id: 'C11', src: 'AC77', q: 'Lumbar puncture is generally performed for patients in which position and vertebral level?', o: ['Flexion, L1–2', 'Extension, L1–2', 'Flexion, L3–4', 'Extension, L3–4', 'Lying on the side, L4–5'], a: 2, ex: 'Flexing the spine widens the interspinous and interlaminar spaces, and entering at L3–L4 (or L4–L5) stays safely below the conus medullaris (L1–L2).', flag: 'Option E (“Lying on the side, L4–5”) is also a valid clinical LP setup if flexed; the key (C) emphasises spinal flexion to widen the interlaminar gap.' },
    { id: 'C12', src: 'AC79', q: 'Where is the most common site of lumbar puncture and what is the landmark for determining the site?', o: ['L1–L2, AIIS', 'L3–L4, AIIS', 'L1–L2, Iliac crest', 'L3–L4, Iliac crest', 'L5–L6, Iliac crest'], a: 3, ex: 'A horizontal line across the highest points of the iliac crests (supracristal / Tuffier’s line) crosses the L4 spinous process or L4–L5 space, guiding safe LP entry at L3–L4 or L4–L5 below the conus medullaris (L1–L2).' }
  ]);
  CVS.after('C-C3', [
    { id: 'C15', src: 'AC71', core: true, q: 'ข้อใดที่สัมพันธ์กัน (Which pairing is correct?)', o: ['Dorsolateral sulcus – lateral horn', 'Ventrolateral sulcus – lateral horn', 'Dorsolateral sulcus – dorsal nerve root', 'Ventral median fissure – ventral nerve root', 'Ventrolateral sulcus – anterior spinal artery'], a: 2, ex: 'Dorsal (sensory) rootlets enter along the dorsolateral sulcus. Ventral (motor) rootlets exit along the ventrolateral sulcus, and the anterior spinal artery runs in the ventral median fissure.' }
  ]);
  CVS.after('C-C4', [
    { id: 'C18', src: 'AC68', core: true, q: 'Anterior spinal artery เลี้ยงโครงสร้างใดของไขสันหลัง (What does the anterior spinal artery supply?)', o: ['Ventral horn &amp; lateral column', 'Ventral horn &amp; dorsal horn', 'Dorsal horn &amp; lateral column', 'Dorsal horn &amp; dorsal column'], a: 0, ex: 'The single anterior spinal artery supplies the anterior two-thirds of the cord—ventral horns, anterior columns, and lateral columns. The paired posterior spinal arteries supply the posterior one-third (dorsal columns and dorsal horns).', flag: 'Recalled as “anterior vertebral artery”; refers to the anterior spinal artery.' },
    { id: 'C19', src: 'AC72 · AC79', q: 'Which structure is mainly supplied by the posterior radicular artery?', o: ['Thoracic spine of vertebral column', 'Anterior 2/3 of spinal cord', 'Dorsal nerve roots', 'Dorsal side of spinal cord', 'Central canal'], a: 2, ex: 'Radicular arteries supply the nerve roots themselves: posterior radicular arteries supply the dorsal nerve roots (and anterior radicular arteries supply the ventral roots). The dorsal one-third of the cord parenchyma is supplied by the posterior spinal arteries.' },
    { id: 'C20', src: 'AC73 · AC77 · AC78', q: 'The biggest segmental spinal artery (artery of Adamkiewicz) can be found at which spinal level?', o: ['T6–10', 'T9–12', 'T2–5', 'C5–T1', 'L3–S2'], a: 1, ex: 'The great anterior segmental medullary artery (artery of Adamkiewicz) is the largest reinforcing vessel to the anterior spinal artery, most commonly arising on the left at T9–T12 (AC77 keyed T10–T12).' },
    { id: 'C21', src: 'AC74', q: 'Which one is the artery of Adamkiewicz?', o: ['Anterior spinal artery', 'Internal thoracic artery', 'Posterior radicular artery', 'Anterior radicular artery', 'Segmental medullary artery'], a: 3, ex: 'The artery of Adamkiewicz is classically named arteria radicularis magna (great anterior radicular artery) in older texts, and classified in modern anatomy as the great anterior segmental medullary artery reinforcing the lower anterior spinal artery.', flag: 'AC74 yellow key marked D (anterior radicular artery, from “arteria radicularis magna”); note that modern texts classify it as the largest anterior segmental medullary artery (E).' }
  ]);
  CVS.after('C-C5', [
    { id: 'C24', src: 'AC73', q: 'Which nerve fiber has the smallest diameter?', o: ['Motor fiber', 'Fast pain fiber', 'Slow pain fiber', 'Fine touch fiber', 'Proprioceptive fiber'], a: 2, ex: 'Slow pain is carried by unmyelinated C fibres (0.2–1.5 μm), which have the smallest diameter and slowest conduction velocity. Fast pain is Aδ, fine touch Aβ, and motor/proprioception Aα.' },
    { id: 'C25', src: 'AC78', q: 'Which type of nerve fiber is unmyelinated?', o: ['Motor fiber', 'Fast pain fiber', 'Slow pain fiber', 'Fine touch fiber', 'Proprioceptive fiber'], a: 2, ex: 'Only type C fibres (slow, dull, aching pain and postganglionic autonomic fibres) are unmyelinated; all A fibres (Aα motor/proprioception, Aβ fine touch, Aδ fast pain) and B fibres are myelinated.' }
  ]);
  CVS.after('C-C6', [
    { id: 'C28', src: 'AC77', q: 'Which nerve injury may require axon grafting?', o: ['Neurapraxia', 'Axonotmesis', 'Neurotmesis', 'Neurapraxia and Axonotmesis', 'Axonotmesis and Neurotmesis'], a: 2, ex: 'In neurapraxia (myelin only) and axonotmesis (endoneurial tube intact), spontaneous recovery occurs. Only neurotmesis (complete transection of nerve and sheaths) requires surgical repair—direct suture if clean with no gap, or nerve grafting (e.g. sural nerve) across a gap.' }
  ]);
  CVS.after('K-C1', [
    { id: 'K3', src: 'AC68', q: 'กระดูกใดไม่ได้ form เป็น facial skeleton (Which bone does not form part of the facial skeleton?)', o: ['Zygoma', 'Maxilla', 'Nasal', 'Palatine', 'Sphenoid'], a: 4, ex: 'The sphenoid is one of the 8 bones of the neurocranium (cranium), not one of the 14 facial (viscerocranial) bones. Zygoma, maxilla, nasal, and palatine are all paired facial bones.' }
  ]);
  CVS.after('K-C2', [
    { id: 'K6', src: 'AC68 · AC71 · AC74 · AC75 · AC77 · AC78 · AC79', core: true, q: 'Which of the following landmarks is NOT located in the median sagittal plane?', o: ['Pterion', 'Lambda', 'Bregma', 'Gnathion', 'Inion'], a: 0, ex: 'Pterion (and asterion) are paired lateral landmarks on the side of the skull. Bregma, lambda, inion, glabella, nasion, and gnathion all lie on the midline (median sagittal plane).', flag: 'Asked 7 times. AC74 recall dropped “NOT” (leaving A, D, E true); AC79 recall included both Pterion and Asterion (both lateral).' },
    { id: 'K7', src: 'AC70', q: 'จุดเชื่อม coronal suture กับ sagittal suture ชื่ออะไร (What is the junction of the coronal suture and sagittal suture called?)', o: ['Pterion', 'Bregma', 'Lambda', 'Asterion', 'Nasion'], a: 1, ex: 'Bregma is the meeting point of the coronal and sagittal sutures (site of the anterior fontanelle in infants). Lambda is where the sagittal and lambdoid sutures meet.' },
    { id: 'K8', src: 'AC76 · AC78 · AC79', q: 'What is the name of the region where the occipital, parietal, and temporal bones join together?', o: ['Pterion', 'Asterion', 'Glabella', 'Bregma', 'Lambda'], a: 1, ex: 'Asterion is the star-shaped junction of the parietal, occipital, and temporal (mastoid) bones—the site of the posterolateral (mastoid) fontanelle. Pterion joins frontal, parietal, sphenoid, and temporal.' }
  ]);
  CVS.after('K-C5', [
    { id: 'K18', src: 'AC72 · AC73', core: true, q: 'A 25-year-old patient was in a car accident and presents with CSF otorrhea, facial palsy, and sensorineural hearing loss. Where is the lesion located?', o: ['Ethmoid', 'Lesser wing of sphenoid', 'Greater wing of sphenoid', 'Petrous portion of temporal bone', 'Mastoid process'], a: 3, ex: 'The internal acoustic meatus, facial canal, and inner ear all lie inside the petrous part of the temporal bone. A petrous temporal fracture tears the meninges and injures CN VII (facial palsy) and CN VIII (sensorineural hearing loss/vertigo) while leaking CSF through the ear (CSF otorrhea).', flag: 'AC70–75 Ch26 yellow key mistakenly highlighted E (mastoid process); AC76–78 Ch7 Q19 and AC73 both correctly key D (petrous portion of temporal bone).' },
    { id: 'K19', src: 'AC72 · AC78', q: 'Fracture at which bone of the skull poses the most risk to optic nerve (and ophthalmic artery) injury?', o: ['Ethmoid', 'Frontal', 'Occipital', 'Vomer', 'Sphenoid'], a: 4, ex: 'The optic nerve (CN II) and ophthalmic artery pass through the optic canal, which runs through the lesser wing/body of the sphenoid bone—so a sphenoid fracture risks optic nerve and ophthalmic artery injury.' }
  ]);
  CVS.after('Z-C1', [
    { id: 'Z1', src: 'AC70', q: 'หมอเอาเข็มจิ้มบริเวณ scalp เพื่อดู cutaneous sensation คือการทดสอบ nerve อะไร (A doctor pricks the anterior scalp to test cutaneous sensation. Which nerve is being tested?)', o: ['Ophthalmic nerve', 'Maxillary nerve', 'Mandibular nerve', 'Facial nerve', 'Oculomotor nerve'], a: 0, ex: 'The anterior scalp up to the vertex is innervated by the supraorbital and supratrochlear branches of the ophthalmic nerve (V1). Facial and oculomotor nerves are motor to this region.', flag: 'Assumes the anterior scalp (V1); note that the temporal scalp is supplied by V3 (auriculotemporal) and the posterior scalp by C2–C3 (greater/lesser occipital).' }
  ]);
  CVS.after('Z-C2', [
    { id: 'Z3', src: 'AC76 · AC78', core: true, q: 'Which condition is most likely to be expected when superior cerebral vein (bridging vein) injury is suspected?', o: ['Subarachnoid hemorrhage', 'Intrapontine hemorrhage', 'Subdural hemorrhage', 'Epidural hemorrhage', 'Basal ganglia hemorrhage'], a: 2, ex: 'Superior cerebral (bridging) veins cross the subdural border layer to empty into the superior sagittal sinus. Tearing them causes venous bleeding deep to the dura mater: a subdural hematoma (contrast with middle meningeal artery → epidural hematoma).' }
  ]);
  CVS.after('Z-C3', [
    { id: 'Z5', src: 'AC75', core: true, q: 'What is the fold of dura mater that separates the cerebrum from the cerebellum?', o: ['Falx cerebri', 'Falx cerebelli', 'Tentorium cerebelli', 'Granular foveolae', 'Diaphragma sellae'], a: 2, ex: 'The tentorium cerebelli forms a horizontal dural tent separating the occipital lobes of the cerebrum above (supratentorial) from the cerebellum and brainstem below (infratentorial). Falx cerebri separates the two cerebral hemispheres; diaphragma sellae roofs the pituitary fossa.' },
    { id: 'Z6', src: 'AC72', q: 'Which structure is located in the infratentorial space?', o: ['Optic nerve', 'Cerebellum', 'Occipital lobe', 'Inferior sagittal sinus', 'Middle cerebral artery'], a: 1, ex: 'Below the tentorium cerebelli (infratentorial / posterior cranial fossa) lie the cerebellum and brainstem. The optic nerve, occipital lobe, inferior sagittal sinus, and MCA are all supratentorial.' },
    { id: 'Z7', src: 'AC79', q: 'Which structure is NOT in the infratentorial space?', o: ['Optic nerve', 'Abducens nerve', 'Glossopharyngeal nerve', 'Accessory nerve', 'Hypoglossal nerve'], a: 0, ex: 'CN II (optic nerve) belongs to the forebrain/diencephalon and lies above the tentorium (supratentorial). CN VI (pons) and CN IX, XI, XII (medulla) all emerge from the brainstem in the infratentorial posterior cranial fossa.' }
  ]);
  CVS.after('Z-C4', [
    { id: 'Z9', src: 'AC68', q: 'In case of pathology of the pons, which cranial nerve is least likely to be affected?', o: ['Trigeminal nerve', 'Oculomotor nerve', 'Abducens nerve', 'Facial nerve', 'Vestibulocochlear nerve'], a: 1, ex: 'The oculomotor nerve (CN III) emerges from the midbrain (interpeduncular fossa), not the pons. CN V emerges from the lateral pons, and CN VI, VII, and VIII emerge at the pontomedullary junction.' },
    { id: 'Z10', src: 'AC73', core: true, q: 'Nerve เส้นไหนออกมาจาก dorsal surface of brainstem (Which cranial nerve emerges from the dorsal surface of the brainstem?)', o: ['CN III', 'CN IV', 'CN V', 'CN VI', 'CN VIII'], a: 1, ex: 'The trochlear nerve (CN IV) is the ONLY cranial nerve to emerge from the dorsal aspect of the brainstem (just below the inferior colliculi of the midbrain), and its fibres decussate before exiting.' },
    { id: 'Z11', src: 'AC74', q: 'In case of pathology of the medulla, which nerve is most likely to be affected?', o: ['Optic nerve', 'Trochlear nerve', 'Trigeminal nerve', 'Occipital nerve', 'Hypoglossal nerve'], a: 4, ex: 'CN IX, X, XI, and XII (hypoglossal nerve) emerge from the medulla oblongata. CN II is forebrain, CN IV midbrain, CN V pons, and the occipital nerves are cervical spinal nerves (C2–C3).' }
  ]);
  CVS.after('Z-C5', [
    { id: 'Z14', src: 'AC70', q: 'ผู้ป่วยติดเชื้อตรง dural venous sinus ใกล้ pituitary gland ติดเชื้อ sinus อะไร (A patient has an infection in the dural venous sinus next to the pituitary gland. Which sinus is involved?)', o: ['Straight sinus', 'Sigmoid sinus', 'Cavernous sinus', 'Greater petrosal sinus', 'Confluence of sinuses'], a: 2, ex: 'The paired cavernous sinuses flank the body of the sphenoid and pituitary gland (sella turcica). Infection here (cavernous sinus thrombosis) threatens CN VI and the ICA inside, plus CN III, IV, V1, V2 in its lateral wall.' },
    { id: 'Z15', src: 'AC72', core: true, q: 'Which of the following is NOT a component of the circle of Willis?', o: ['Internal carotid artery', 'Middle cerebral artery', 'Posterior cerebral artery', 'Anterior cerebral artery', 'Anterior communicating artery'], a: 1, ex: 'The arterial circle of Willis is formed by the anterior communicating artery, paired ACAs, terminal internal carotid arteries, paired posterior communicating arteries, and paired PCAs. The middle cerebral artery (MCA) runs laterally out of the circle and is not part of the anastomotic ring itself.' },
    { id: 'Z16', src: 'AC78', q: 'Which dural venous sinus is directly connected to the internal jugular vein?', o: ['Inferior sagittal sinus', 'Sigmoid sinus', 'Transverse sinus', 'Superior sagittal sinus', 'Confluence of sinuses'], a: 1, ex: 'Venous blood flows from the confluence → transverse sinus → sigmoid sinus, which passes through the jugular foramen to continue directly as the internal jugular vein.' },
    { id: 'Z17', src: 'AC79', q: 'The anterior compartment of cranial vascular supply (anterior circulation) is occluded. Which artery is NOT affected?', o: ['Anterior cerebral artery', 'Internal carotid artery', 'Middle cerebral artery', 'Vertebral artery', 'Posterior communicating artery'], a: 3, ex: 'The anterior circulation derives from the internal carotid artery (ICA → ACA, MCA, ophthalmic, PCom). The vertebral arteries, basilar artery, and PCAs form the posterior (vertebrobasilar) circulation.' }
  ]);
  CVS.after('F-C1', [
    { id: 'F7', src: 'AC71 · AC73 · AC75 · AC76', q: 'Which muscle is intensively used when playing the trumpet (compressing the cheek during blowing/whistling)?', o: ['Digastric muscle', 'Buccinator muscle', 'Masseter muscle', 'Orbicularis oris muscle', 'Medial pterygoid muscle'], a: 1, ex: 'Buccinator (“the trumpeter’s muscle”, CN VII) compresses the cheek against the molar teeth to keep food between the teeth during chewing and to expel air forcibly when blowing a trumpet or whistling.', flag: 'AC71 yellow key mistakenly highlighted D (orbicularis oris); AC73, AC75, and AC76 all correctly key buccinator.' },
    { id: 'F8', src: 'AC77', q: 'If the facial nerve is damaged, which muscle will NOT be affected?', o: ['Temporalis muscle', 'Orbicularis oculi muscle', 'Zygomaticus major muscle', 'Buccinator muscle', 'Orbicularis oris muscle'], a: 0, ex: 'Temporalis is a muscle of mastication innervated by the mandibular nerve (V3), not CN VII. Orbicularis oculi, zygomaticus major, buccinator, and orbicularis oris are all facial expression muscles (CN VII).' }
  ]);
  CVS.after('F-C2', [
    { id: 'F9', src: 'AC73', q: 'Which artery supplies the lower part of the face?', o: ['Facial artery', 'Lingual artery', 'Buccal artery', 'Superior thyroid artery', 'Transverse facial artery'], a: 0, ex: 'The facial artery (from the external carotid) hooks over the inferior border of the mandible just anterior to masseter and ascends across the lower and middle face (giving inferior and superior labial and angular branches).' }
  ]);
  CVS.after('F-C3', [
    { id: 'F11', src: 'AC68', q: 'Which structure is accompanied by the buccal branch of the facial nerve?', o: ['Submandibular duct', 'Parotid duct', 'Stylohyoid ligament', 'Hypoglossal nerve', 'Lingual nerve'], a: 1, ex: 'The buccal branch of CN VII runs horizontally across masseter right beside the parotid (Stensen’s) duct as the duct travels forward to pierce buccinator opposite the upper second molar.' },
    { id: 'F12', src: 'AC70 · AC78', q: 'Which muscle is supplied by the marginal mandibular branch of the facial nerve?', o: ['Depressor labii inferioris', 'Platysma', 'Procerus', 'Zygomaticus major', 'Orbicularis oculi'], a: 0, ex: 'The marginal mandibular branch of CN VII runs along the lower jaw to supply the depressors of the lower lip and chin—depressor labii inferioris, depressor anguli oris (tested in AC70), and mentalis. Platysma is supplied by the cervical branch.' },
    { id: 'F13', src: 'AC79', q: 'Which branch of the facial nerve is related to elevating the upper lip?', o: ['Zygomaticotemporal branch', 'Temporal branch', 'Buccal branch', 'Marginal mandibular branch', 'Cervical branch'], a: 2, ex: 'The buccal branch of CN VII innervates the upper-lip elevators (levator labii superioris, levator anguli oris, zygomaticus muscles) along with buccinator and orbicularis oris. Note that “zygomaticotemporal” is a sensory branch of V2, not CN VII.' }
  ]);
  CVS.after('F-C4', [
    { id: 'F15', src: 'AC68', q: 'An old woman is suffering from numbness of the tip of the nose. Which nerve is damaged?', o: ['Facial nerve', 'Maxillary nerve', 'Mandibular nerve', 'Ophthalmic nerve'], a: 3, ex: 'The dorsum and tip of the nose are supplied by the external nasal nerve, a terminal branch of the nasociliary nerve from the ophthalmic division (V1)—a classic trap because students expect the middle face to be all V2.' },
    { id: 'F16', src: 'AC73 · AC77', q: 'Which nerve provides sensory innervation to the lower part of the forehead (medial)?', o: ['Supraorbital nerve', 'Supratrochlear nerve', 'Infratrochlear nerve', 'Infraorbital nerve', 'Nasociliary nerve'], a: 1, ex: 'The supratrochlear nerve (V1) supplies the lower medial forehead (glabella region) and medial upper eyelid. The supraorbital nerve supplies the upper/lateral forehead back to the vertex, while the infratrochlear nerve supplies the medial canthus and bridge of the nose.', flag: 'AC73 Thai wording (“ใต้หน้าผากฝั่ง medial”) led AC70–75 to highlight infratrochlear, while AC76–78 keyed supratrochlear. “Lower part of the forehead” is strictly supratrochlear (B).' },
    { id: 'F17', src: 'AC74', q: 'A female patient came to the hospital with chronic pain behind the right ear extending toward the occipital area. Which spinal nerve level is affected?', o: ['C1', 'C2–3', 'C4–5', 'Facial nerve', 'Trigeminal nerve'], a: 1, ex: 'The skin behind the ear and over the occipital scalp is supplied by cervical plexus/dorsal ramus nerves from C2–C3 (greater occipital C2, lesser occipital C2, great auricular C2–C3). C1 has no cutaneous dermatome.' },
    { id: 'F18', src: 'AC74', q: 'Which of the following transmits sensation from the skin of the lower lip to the chin?', o: ['Mental nerve', 'Buccal nerve', 'Cervical branch of facial nerve', 'Marginal mandibular branch of the facial nerve'], a: 0, ex: 'The mental nerve (terminal branch of the inferior alveolar nerve, V3) exits the mental foramen to supply sensory innervation to the lower lip and chin. The marginal mandibular branch of CN VII is purely motor to the muscles of the same region.' }
  ]);
  CVS.after('F-C5', [
    { id: 'F21', src: 'AC68 · AC72', core: true, q: 'Which of the following vessels is NOT involved in the blood circulation of the thyroid gland?', o: ['Thyrocervical trunk', 'Internal jugular vein', 'Brachiocephalic vein', 'Internal carotid artery', 'External carotid artery'], a: 3, ex: 'Thyroid arterial supply comes from the superior thyroid artery (external carotid) and inferior thyroid artery (thyrocervical trunk of subclavian). Venous drainage goes via superior and middle thyroid veins to the internal jugular vein, and inferior thyroid veins to the brachiocephalic veins. The internal carotid artery gives no branches in the neck (and AC72 tested the same question with “subclavian vein” as the non-thyroid distractor).' },
    { id: 'F22', src: 'AC70', q: 'Which of the following is NOT a content of the muscular triangle?', o: ['Thyroid cartilage', 'External jugular vein', 'Sternothyroid muscle', 'Superior thyroid artery', 'Parathyroid glands'], a: 1, ex: 'The external jugular vein runs superficially over sternocleidomastoid into the posterior (subclavian) triangle. The muscular triangle contains the infrahyoid strap muscles (sternohyoid, sternothyroid), thyroid and parathyroid glands, thyroid vessels, larynx (thyroid cartilage), and trachea.' },
    { id: 'F23', src: 'AC74', core: true, q: 'Which nerve supplies the thyrohyoid muscle?', o: ['Vagus nerve', 'Facial nerve', 'Mandibular nerve', 'First cervical nerve', 'Glossopharyngeal nerve'], a: 3, ex: 'All infrahyoid (strap) muscles are supplied by the ansa cervicalis (C1–C3) EXCEPT thyrohyoid, which is supplied directly by C1 (first cervical nerve) fibres hitchhiking along the hypoglossal nerve (CN XII)—the same C1 pathway that supplies geniohyoid.' },
    { id: 'F24', src: 'AC77 · AC78', q: 'In which region of the neck is the arterial pulse commonly palpated?', o: ['Carotid triangle', 'Submandibular triangle', 'Submental triangle', 'Occipital triangle', 'Muscular triangle'], a: 0, ex: 'The carotid triangle (bounded by SCM, superior belly of omohyoid, and posterior belly of digastric) contains the common carotid artery bifurcation into internal and external carotids—the classic site to palpate the carotid pulse.' },
    { id: 'F25', src: 'AC79', q: 'Which muscle is NOT supplied by the ansa cervicalis?', o: ['Stylohyoid', 'Sternohyoid', 'Sternothyroid', 'Superior omohyoid', 'Inferior omohyoid'], a: 0, ex: 'Sternohyoid, sternothyroid, and both bellies of omohyoid are infrahyoid strap muscles innervated by ansa cervicalis (C1–C3). Stylohyoid is a suprahyoid (2nd-arch) muscle innervated by the facial nerve (CN VII).' },
    { id: 'F26', src: 'AC79', q: 'Which structure is NOT located in the digastric (submandibular) triangle?', o: ['Hypoglossal nerve', 'Facial artery', 'Submandibular gland', 'Ansa cervicalis', 'Mylohyoid muscle'], a: 3, ex: 'The digastric (submandibular) triangle holds the submandibular gland, facial artery and vein, and hypoglossal nerve, with mylohyoid and hyoglossus forming its floor. The ansa cervicalis lies lower down on the carotid sheath inside the carotid and muscular triangles.' }
  ]);
  CVS.after('D-C1', [
    { id: 'D3', src: 'AC70 · AC74', q: 'Which structure forms the medial boundary of the infratemporal fossa?', o: ['Ramus of mandible', 'Styloid process', 'Lateral pterygoid plate', 'Posterior surface of mandible', 'Coronoid process of mandible'], a: 2, ex: 'Boundaries of the infratemporal fossa: lateral = ramus of mandible, medial = lateral pterygoid plate, anterior = posterior surface of maxilla, roof = greater wing of sphenoid.' },
    { id: 'D4', src: 'AC71', q: 'Lateral border ของ infratemporal fossa คือโครงสร้างใด (What forms the lateral border of the infratemporal fossa?)', o: ['Ramus of mandible', 'Condyloid process of mandible', 'Styloid process'], a: 0, ex: 'The infratemporal fossa sits immediately deep to the ramus of the mandible, which forms its lateral boundary.', flag: 'Only three options were recalled.' }
  ]);
  CVS.after('D-C2', [
    { id: 'D11', src: 'AC68', q: 'กล้ามเนื้อมัดใดมีหน้าที่หลักในการ protrusion ของคาง (Which muscle is the prime mover for protrusion of the chin/mandible?)', o: ['Temporalis', 'Masseter', 'Deep head of medial pterygoid', 'Superficial head of medial pterygoid', 'Lateral pterygoid'], a: 4, ex: 'Bilateral contraction of the lateral pterygoid pulls the condylar neck and TMJ disc forward onto the articular tubercle, making it the prime mover for protruding (and depressing/opening) the mandible; medial pterygoid and superficial masseter only assist.' },
    { id: 'D12', src: 'AC70', q: 'Which muscle originates from the maxillary tuberosity?', o: ['Medial pterygoid', 'Lateral pterygoid', 'Buccinator', 'Tensor veli palatini', 'Masseter'], a: 0, ex: 'The medial pterygoid has two heads: a superficial head arising from the maxillary tuberosity (and pyramidal process of the palatine bone) and a deep head from the medial surface of the lateral pterygoid plate.' },
    { id: 'D13', src: 'AC71', q: 'Which muscle has the inferior border and medial surface of the zygomatic arch as its origin?', o: ['Masseter muscle', 'Buccinator muscle', 'Lateral pterygoid muscle', 'Medial pterygoid muscle'], a: 0, ex: 'Masseter originates from the inferior border and medial surface of the zygomatic arch and inserts onto the lateral surface of the ramus and angle of the mandible.' },
    { id: 'D14', src: 'AC72', q: 'กล้ามเนื้ออะไรเกาะจากด้าน medial side of lateral pterygoid plate (Which muscle originates from the medial surface of the lateral pterygoid plate?)', o: ['Medial pterygoid muscle', 'Lateral pterygoid muscle', 'Buccinator muscle', 'Masseter muscle', 'Temporalis muscle'], a: 0, ex: 'The deep head of the medial pterygoid arises from the medial surface of the lateral pterygoid plate (whereas the inferior head of the lateral pterygoid arises from its lateral surface).' }
  ]);
  CVS.after('D-C3', [
    { id: 'D17', src: 'AC71', q: 'Which branch of the external carotid artery supplies the upper and lower jaws and nasal cavity and accompanies many branches of the trigeminal nerve?', o: ['Facial artery', 'Lingual artery', 'Maxillary artery', 'Occipital artery', 'Superior thyroid artery'], a: 2, ex: 'The maxillary artery (the larger terminal branch of the ECA) runs through the infratemporal and pterygopalatine fossae, supplying the lower jaw (inferior alveolar a.), upper jaw (superior alveolar/palatine aa.), and nasal cavity (sphenopalatine a.) alongside V2 and V3 branches.', flag: 'Recalled as “accumulate with many branch of trigeminal”; read “accompany”.' },
    { id: 'D18', src: 'AC71 · AC73', core: true, q: 'Which of the following veins connects the facial vein and the pterygoid venous plexus?', o: ['Deep facial vein', 'Deep auricular vein', 'Retromandibular vein', 'Inferior ophthalmic vein', 'Superior ophthalmic vein'], a: 0, ex: 'The deep facial vein bridges the facial vein on the cheek directly to the pterygoid venous plexus in the infratemporal fossa—providing a valveless route for facial infections to reach the cavernous sinus via emissary veins.' },
    { id: 'D19', src: 'AC72', q: 'Which of the following does NOT arise from the first (mandibular) part of the maxillary artery?', o: ['Deep auricular artery', 'Deep tympanic artery', 'Middle meningeal artery', 'Inferior alveolar artery', 'Anterior tympanic artery'], a: 1, ex: 'The five branches of the 1st (mandibular) part of the maxillary artery are deep auricular, anterior tympanic, middle meningeal, accessory meningeal, and inferior alveolar (“DAMAI”). There is no “deep tympanic artery.”' }
  ]);
  CVS.after('D-C4', [
    { id: 'D25', src: 'AC70', q: 'ข้อใดต่อไปนี้เป็น motor nerve ของ mandibular nerve (Which of the following is a motor branch of the mandibular nerve?)', o: ['Auriculotemporal nerve', 'Buccal nerve', 'Inferior alveolar nerve', 'Deep temporal nerve', 'Lingual nerve'], a: 3, ex: 'The deep temporal nerves (anterior and posterior) are motor branches of the anterior division of V3 supplying the temporalis muscle. Auriculotemporal, buccal, lingual, and inferior alveolar (main trunk) are sensory.' },
    { id: 'D26', src: 'AC78', core: true, q: 'A patient has loss of sensation and taste at the anterior part of the tongue after having a dental procedure. Which nerve is most likely affected?', o: ['Inferior alveolar nerve', 'Lingual nerve', 'Buccal nerve', 'Hypoglossal nerve', 'Glossopharyngeal nerve'], a: 1, ex: 'After chorda tympani (CN VII, taste) joins the lingual nerve (V3, general sensation) in the infratemporal fossa, both modalities travel together in the lingual nerve close to the lower third molar. Injuring the lingual nerve during dental work knocks out BOTH general sensation and taste on the anterior two-thirds of the tongue.' }
  ]);
  CVS.after('D-C5', [
    { id: 'D28', src: 'AC77', core: true, q: 'Which choice represents the correct venous drainage sequence of the face to the cavernous sinus?', o: ['Facial vein → Deep facial vein → Pterygoid plexus → Emissary vein → Cavernous sinus', 'Facial vein → Angular vein → Superficial temporal vein → Pterygoid plexus → Cavernous sinus', 'Facial vein → Pterygoid plexus → Deep facial vein → Superficial temporal vein → Emissary vein', 'Facial vein → Superficial temporal vein → Deep facial vein → Pterygoid plexus → Cavernous sinus', 'Facial vein → Supraorbital vein → Angular vein → Pterygoid plexus → Cavernous sinus'], a: 0, ex: 'Infection in the danger triangle spreads along two valveless paths to the cavernous sinus: superiorly via angular → ophthalmic veins, or deeply via facial vein → deep facial vein → pterygoid venous plexus → emissary vein (through foramen ovale) → cavernous sinus.' },
    { id: 'D29', src: 'AC77', q: 'The inferior alveolar nerve provides sensation to which area?', o: ['Lower lip', 'Upper lip', 'Anterior two-thirds of the tongue', 'Posterior one-third of the tongue', 'Palate'], a: 0, ex: 'The inferior alveolar nerve supplies the lower teeth and gingiva inside the mandibular canal, then exits the mental foramen as the mental nerve to supply the lower lip and chin—which is why an inferior alveolar nerve block numbs the lower lip.' }
  ]);
  CVS.after('O-C1', [
    { id: 'O1', src: 'AC72 · AC75', core: true, q: 'Which artery supplies the pulp of the teeth?', o: ['Facial artery', 'Lingual artery', 'Maxillary artery', 'Transverse facial artery', 'Sublingual artery'], a: 2, ex: 'Both upper and lower teeth are fed by branches of the maxillary artery: superior alveolar arteries (upper teeth) and the inferior alveolar artery (lower teeth).' },
    { id: 'O2', src: 'AC71', q: 'Which nerve innervates the teeth?', o: ['Lingual nerve', 'Infraorbital nerve', 'Maxillary nerve', 'Ophthalmic nerve', 'Zygomaticofacial nerve'], a: 2, ex: 'The maxillary nerve (V2) gives the superior alveolar nerves to the upper teeth (the lower teeth are supplied by the inferior alveolar branch of V3, which is not listed).' },
    { id: 'O3', src: 'AC74', q: 'Which structure attaches the root of a tooth to the alveolar bone?', o: ['Dentin', 'Enamel', 'Periodontal ligament', 'Dental pulp', 'Gingiva'], a: 2, ex: 'The periodontal ligament is the dense fibrous tissue anchoring the cementum of the tooth root to the alveolar socket (a gomphosis joint).' }
  ]);
  CVS.after('O-C2', [
    { id: 'O8', src: 'AC74 · AC77', core: true, q: 'Which muscle arises from the mandible and protrudes the tongue?', o: ['Styloglossus', 'Stylohyoid', 'Mylohyoid', 'Genioglossus', 'Palatoglossus'], a: 3, ex: 'Genioglossus fans backward from the superior mental spine of the mandible into the tongue; its posterior fibres pull the tongue forward (protrusion) and keep it from falling back into the airway.' },
    { id: 'O9', src: 'AC78', core: true, q: 'A man complains of difficulty swallowing, frequent aspiration, difficulty in phonation, and abnormal placement of his tongue. Oral examination shows protrusion with left deviation of the tongue. Which nerve is most likely harmed?', o: ['Left lingual nerve', 'Right lingual nerve', 'Left hypoglossal nerve', 'Right hypoglossal nerve', 'Left glossopharyngeal nerve'], a: 2, ex: 'Hypoglossal nerve (CN XII) palsy weakens the ipsilateral genioglossus. On protrusion the intact right genioglossus pushes the tongue toward the weak side, so left deviation points to a left hypoglossal nerve lesion (“licks the lesion”).', flag: 'The recalled stem also mentioned mild atrophy of the right submandibular gland, which does not fit an isolated left CN XII lesion; focus on the tongue deviation.' },
    { id: 'O10', src: 'AC75', q: 'Which muscle inserts along the side of the tongue and reaches the tip of the tongue?', o: ['Hyoglossus', 'Styloglossus', 'Palatoglossus', 'Stylohyoid', 'Posterior belly of digastric'], a: 1, ex: 'Styloglossus runs forward from the styloid process along the lateral border of the tongue all the way to the tip, retracting and curling the tongue upward.' }
  ]);
  CVS.after('O-C3', [
    { id: 'O14', src: 'AC70', core: true, q: 'Which nerve supplies taste sensation to the anterior two-thirds of the tongue?', o: ['Hypoglossal nerve', 'Vagus nerve', 'Glossopharyngeal nerve', 'Chorda tympani', 'Lingual nerve'], a: 3, ex: 'Taste from the anterior two-thirds of the tongue travels in the chorda tympani (CN VII), hitchhiking on the lingual nerve (V3). General sensation there is the lingual nerve itself; posterior one-third taste and general sensation are CN IX.' }
  ]);
  CVS.after('O-C4', [
    { id: 'O27', src: 'AC74 · AC76 · AC77', q: 'Which muscle runs from the mandible to the hyoid bone, forming the true floor of the mouth and the lower border of the sublingual space?', o: ['Stylohyoid', 'Styloglossus', 'Mylohyoid', 'Genioglossus', 'Palatoglossus'], a: 2, ex: 'The two mylohyoid muscles form the muscular diaphragm (floor) of the mouth, separating the sublingual space above from the submandibular space below.', flag: 'AC76 recalled a typo “Myoglossus” for mylohyoid; AC77 keyed both mylohyoid and geniohyoid because the lecture slide lists both in the floor of the mouth.' },
    { id: 'O28', src: 'AC76', q: 'Which muscle is innervated by the mandibular nerve (CN V3)?', o: ['Stylohyoid muscle', 'Hyoglossus muscle', 'Anterior belly of digastric', 'Geniohyoid muscle', 'Omohyoid muscle'], a: 2, ex: 'The nerve to mylohyoid (from inferior alveolar nerve, V3) supplies mylohyoid and the anterior belly of digastric. Stylohyoid is CN VII, hyoglossus CN XII, geniohyoid C1 via CN XII, omohyoid ansa cervicalis.' },
    { id: 'O29', src: 'AC77', q: 'Which of the following structures travels through the submandibular gland?', o: ['Lingual artery', 'Facial artery', 'Submental artery', 'Inferior alveolar artery', 'Maxillary artery'], a: 1, ex: 'The facial artery grooves and passes through the posterior part of the submandibular gland before hooking around the inferior border of the mandible onto the face.' }
  ]);
  CVS.after('O-C5', [
    { id: 'O34', src: 'AC76', core: true, q: 'A 56-year-old man presents with 3 days of dysphagia to solids and liquids and hoarseness. Examination reveals decreased sensation over the posterior aspect of the tongue, and the uvula deviates toward the right side. The uvula deviation suggests loss of function of which nerve?', o: ['Right glossopharyngeal nerve', 'Right vagus nerve', 'Left hypoglossal nerve', 'Left glossopharyngeal nerve', 'Left vagus nerve'], a: 4, ex: 'All muscles of the soft palate (except tensor veli palatini, V3) and all pharyngeal muscles (except stylopharyngeus, IX) are supplied by the vagus nerve (CN X). A left vagus lesion drops the left palatal arch, so the intact right side pulls the uvula to the right (away from the lesion).' }
  ]);
  CVS.after('J-C1', [
    { id: 'J1', src: 'AC75 · AC77', core: true, q: 'Which of the following structures is found only on the right side of the body?', o: ['Brachiocephalic artery', 'Brachiocephalic vein', 'Thoracic duct', 'Inferior thyroid vein', 'Recurrent laryngeal nerve'], a: 0, ex: 'Only the right common carotid and right subclavian arteries arise from the brachiocephalic trunk (artery). On the left, both arise directly from the aortic arch. Brachiocephalic veins and recurrent laryngeal nerves are paired.' },
    { id: 'J2', src: 'AC68', core: true, q: 'If radiopaque contrast is injected into the external carotid artery, in which artery will contrast NOT be seen?', o: ['Superior thyroid artery', 'Inferior thyroid artery', 'Lingual artery', 'Maxillary artery', 'Superficial temporal artery'], a: 1, ex: 'The inferior thyroid artery arises from the thyrocervical trunk of the subclavian artery, not the external carotid. Superior thyroid, lingual, maxillary and superficial temporal are all ECA branches.' },
    { id: 'J3', src: 'AC70', core: true, q: 'Which of the following is NOT a branch of the subclavian artery?', o: ['Vertebral artery', 'Internal thoracic artery', 'Thyrocervical trunk', 'Costocervical trunk', 'Superior thyroid artery'], a: 4, ex: 'Subclavian branches: vertebral, internal thoracic and thyrocervical trunk (1st part), costocervical trunk (2nd part), dorsal scapular (3rd part). Superior thyroid is the first anterior branch of the external carotid artery.' },
    { id: 'J4', src: 'AC71', q: 'Which of the following arteries branches from the subclavian artery?', o: ['Vertebral artery', 'Subscapular artery', 'Lateral thoracic artery', 'Common carotid artery', 'Thoracoacromial artery'], a: 0, ex: 'The vertebral artery is the first branch of the 1st part of the subclavian artery. Subscapular, lateral thoracic and thoracoacromial are branches of the axillary artery.' },
    { id: 'J5', src: 'AC74', q: 'The artery passing through the foramen transversarium of the cervical vertebrae originates from which vessel?', o: ['Axillary artery', 'Subclavian artery', 'Brachiocephalic trunk', 'External carotid artery', 'Common carotid artery'], a: 1, ex: 'The vertebral artery ascends through the transverse foramina of C6–C1 and originates from the first part of the subclavian artery.', flag: 'In AC74 this was accompanied by an axial CT scan indicating the foramen transversarium (image not reproduced in the AC70–75 PDF).' },
    { id: 'J6', src: 'AC68', q: 'A patient receives a stab wound just above the clavicle (root of the neck). Which structure is NOT likely to be injured?', o: ['Subclavian vein', 'Brachial plexus', 'External carotid artery', 'Phrenic nerve', 'Pleura'], a: 2, ex: 'The external carotid artery begins high in the neck at the carotid bifurcation (C3–C4, upper border of thyroid cartilage). Subclavian vein, brachial plexus, phrenic nerve and the dome of the cervical pleura all lie right above the clavicle.' }
  ]);
  CVS.after('J-C2', [
    { id: 'J8', src: 'AC74', q: 'During central venous catheterization, a needle tip is positioned above the clavicle between the two heads of the sternocleidomastoid muscle. What is the target vein?', o: ['Subclavian vein', 'Internal jugular vein', 'External jugular vein', 'Brachiocephalic vein', 'Anterior jugular vein'], a: 1, ex: 'The triangle between the sternal and clavicular heads of SCM (Sedillot’s triangle) directly overlies the internal jugular vein—the classic central approach landmark.' }
  ]);
  CVS.after('J-C3', [
    { id: 'J12', src: 'AC72 · AC75', core: true, q: 'During thyroidectomy, the superior thyroid artery must be ligated. Which nerve is most likely to be injured?', o: ['Internal laryngeal nerve', 'External laryngeal nerve', 'Superior laryngeal nerve', 'Recurrent laryngeal nerve', 'Vagus nerve'], a: 1, ex: 'The external laryngeal nerve (motor to cricothyroid) runs closely alongside the superior thyroid artery near the upper pole of the thyroid; injury weakens high-pitched voice.' },
    { id: 'J13', src: 'AC68 · AC70 · AC76 · AC79 (Ex)', core: true, q: 'During removal of the thyroid gland, the inferior thyroid artery must be ligated. Which nerve has the highest chance of being injured?', o: ['Vagus nerve', 'Internal laryngeal nerve', 'External laryngeal nerve', 'Superior laryngeal nerve', 'Recurrent laryngeal nerve'], a: 4, ex: 'The recurrent laryngeal nerve ascends in the tracheoesophageal groove right next to the inferior thyroid artery. Injury causes unilateral vocal cord paralysis and hoarseness.', flag: 'AC68 and AC70 tested the same nerve via a post-thyroidectomy hoarseness / unilateral vocal cord paralysis vignette; merged here.' },
    { id: 'J14', src: 'AC78 · AC79', q: 'Which nerve supplies the cricothyroid muscle?', o: ['Pharyngeal branch of glossopharyngeal nerve', 'Pharyngeal branch of vagus nerve', 'External laryngeal nerve', 'Internal laryngeal nerve', 'Inferior root of ansa cervicalis'], a: 2, ex: 'Cricothyroid is the sole intrinsic laryngeal muscle supplied by the external laryngeal nerve (from superior laryngeal n., CN X). All other intrinsic laryngeal muscles are supplied by the recurrent laryngeal nerve.', flag: 'AC79 Q20 asked the same concept with an accompanying diagram of deep neck nerves (image omitted in recall).' },
    { id: 'J15', src: 'AC72', q: 'Which structure is NOT related to the carotid sheath?', o: ['Vagus nerve', 'Phrenic nerve', 'Ansa cervicalis', 'Internal jugular vein', 'Common carotid artery'], a: 1, ex: 'The carotid sheath encloses the common/internal carotid artery, internal jugular vein and vagus nerve, with ansa cervicalis embedded in its anterior wall. The phrenic nerve lies separately on the anterior surface of anterior scalene.' }
  ]);
  CVS.after('J-C4', [
    { id: 'J20', src: 'AC70 · AC71 · AC72 · AC74', core: true, q: 'After surgery for neck cancer, a patient develops ptosis of the right upper eyelid, miosis of the right pupil, and decreased sweating on the right side of the face. Which structure was most likely injured?', o: ['Vagus nerve', 'Glossopharyngeal nerve', 'Trigeminal nerve', 'Facial nerve', 'Cervical sympathetic trunk'], a: 4, ex: 'Ptosis (tarsal muscle), miosis (dilator pupillae) and facial anhidrosis form the classic triad of Horner syndrome from injury to the ipsilateral cervical sympathetic trunk.' },
    { id: 'J21', src: 'AC73', q: 'Which of the following symptoms does NOT represent Horner’s syndrome?', o: ['Ptosis', 'Miosis', 'Enophthalmos', 'Facial anhidrosis', 'Medial strabismus'], a: 4, ex: 'Horner syndrome affects oculosympathetic smooth muscle and sweat glands (ptosis, miosis, apparent enophthalmos, anhidrosis). Medial strabismus results from lateral rectus palsy (CN VI), a somatic nerve.' }
  ]);
  CVS.after('J-C5', [
    { id: 'J26', src: 'AC73 · AC74', core: true, q: 'Where does the thoracic duct open into the blood circulation?', o: ['Junction between the left and right brachiocephalic veins', 'Junction between the left subclavian and internal jugular veins', 'Junction between the left subclavian and external jugular veins', 'Junction between the right subclavian and internal jugular veins', 'Junction between the right subclavian and external jugular veins'], a: 1, ex: 'The thoracic duct arches in the root of the left neck to empty into the left venous angle—the junction of the left internal jugular and left subclavian veins.' },
    { id: 'J27', src: 'AC71 · AC72', q: 'Which part of the body does NOT drain its lymphatics into the thoracic duct?', o: ['Right lower limb', 'Right half of thorax', 'Left half of thorax', 'Right half of abdomen', 'Left half of abdomen'], a: 1, ex: 'The thoracic duct drains everything below the diaphragm plus the left half above it. The right upper quadrant (right head/neck, right upper limb, right half of thorax) drains via the right lymphatic duct.' },
    { id: 'J28', src: 'AC76', q: 'A lactating woman presents with pain, erythema, and swelling of the right breast with enlarged, tender right axillary lymph nodes. Which best describes the lymphatic drainage pathway from the inflamed lymph nodes?', o: ['Drains into the thoracic duct and then the junction between the left subclavian and internal jugular veins', 'Drains into the thoracic duct and then directly into the right heart', 'Drains into the right lymphatic duct and then the junction between the right subclavian and internal jugular veins', 'Drains into the right lymphatic duct and then directly into the superior vena cava', 'Drains into the right lymphatic duct and then into the thoracic duct'], a: 2, ex: 'The right breast and right axillary nodes lie in the right upper quadrant, so they drain via the right lymphatic duct into the right venous angle (right subclavian + right IJV).' },
    { id: 'J29', src: 'AC78', q: 'A patient has bilateral enlargement of the palatine tonsils due to acute bacterial tonsillitis. Two weeks later, secondary lymph node enlargement is detected. Which lymph nodes are affected?', o: ['Supraclavicular lymph nodes', 'Jugulodigastric lymph nodes', 'Maxillary lymph nodes', 'Deep parotid lymph nodes', 'Retropharyngeal lymph nodes'], a: 1, ex: 'The palatine tonsil drains primarily to the jugulodigastric (tonsillar) node of the superior deep cervical chain, felt just below the angle of the mandible.', flag: 'The recall misspelled option B as “Jugulogastric” and the PDF answer table mistakenly printed letter C beside the explanation “Jugulodigastric lymph node”; corrected here to B.' },
    { id: 'J30', src: 'AC79', q: 'An infection caused by poor oral hygiene can spread downward along deep neck fascial planes into which space?', o: ['Pleural space', 'Cardiac space', 'Mediastinum', 'Thoracic duct', 'Peritoneal cavity'], a: 2, ex: 'Oral and submandibular infections (e.g. Ludwig angina) can track posteriorly into the retropharyngeal/danger space (between alar and prevertebral fascia), which extends directly down into the posterior mediastinum.' }
  ]);
  CVS.after('E-C1', [
    { id: 'E5', src: 'AC75 · AC78', core: true, q: 'Which nerve does NOT pass through the superior orbital fissure?', o: ['Oculomotor nerve', 'Frontal nerve', 'Trochlear nerve', 'Optic nerve', 'Lacrimal nerve'], a: 3, ex: 'The superior orbital fissure carries CN III, IV, VI and the three branches of V1 (frontal, lacrimal, nasociliary). The optic nerve (CN II) passes through the optic canal with the ophthalmic artery.' },
    { id: 'E6', src: 'AC70', q: 'A tennis ball strikes the orbit and damages the optic canal. Which structures are most likely affected?', o: ['Optic nerve and ophthalmic artery', 'Optic nerve and ophthalmic nerve', 'Oculomotor nerve and ophthalmic artery', 'Oculomotor nerve and ophthalmic nerve', 'Optic nerve and oculomotor nerve'], a: 0, ex: 'Only two structures traverse the optic canal: the optic nerve (CN II) and the ophthalmic artery. CN III and the ophthalmic nerve (V1) pass through the superior orbital fissure.' }
  ]);
  CVS.after('E-C2', [
    { id: 'E13', src: 'AC72', core: true, q: 'During physical examination, the eyeball is adducted and moved downward. Which extraocular muscle is being tested?', o: ['Superior rectus muscle', 'Lateral rectus muscle', 'Superior oblique muscle', 'Inferior rectus muscle', 'Inferior oblique muscle'], a: 2, ex: 'When the eye is adducted, the obliques align with the visual axis: superior oblique depresses (looks down and in), and inferior oblique elevates (looks up and in).' },
    { id: 'E14', src: 'AC79', q: 'A doctor asks a patient to adduct the eye medially and then look upward. Which muscle is primarily being tested?', o: ['Superior rectus', 'Superior oblique', 'Inferior rectus', 'Inferior oblique', 'Medial rectus'], a: 3, ex: 'From the adducted position, elevation is performed purely by the inferior oblique muscle (CN III).' }
  ]);
  CVS.after('E-C3', [
    { id: 'E15', src: 'AC75', core: true, q: 'The tarsal plate supports which structure?', o: ['Cornea', 'Lens', 'Eyelid', 'Iris', 'Ciliary body'], a: 2, ex: 'The superior and inferior tarsal plates are dense fibrous connective-tissue frames giving shape and support to the eyelids and housing the Meibomian (tarsal) glands.' }
  ]);
  CVS.after('E-C4', [
    { id: 'E18', src: 'AC79', core: true, q: 'Through which structure does the optic nerve pierce the sclera?', o: ['Fovea centralis', 'Trabecular meshwork', 'Zonular fiber', 'Lamina cribrosa', 'Ora serrata'], a: 3, ex: 'Axons of retinal ganglion cells exit the eyeball through the sieve-like lamina cribrosa of the sclera at the optic disc.' },
    { id: 'E19', src: 'AC71', q: 'Which layer of the eyeball is the vascular, pigmented coat?', o: ['Sclera', 'Limbus', 'Cornea', 'Choroid', 'Ora serrata'], a: 3, ex: 'The middle tunic (uvea) consists of iris, ciliary body and choroid; the choroid is richly vascular (nourishing the outer retina) and pigmented (absorbing stray light).' },
    { id: 'E20', src: 'AC79', q: 'Which structure of the eye is commonly used for transplantation (eye donation)?', o: ['Iris', 'Lens', 'Choroid', 'Cornea', 'Conjunctiva'], a: 3, ex: 'The cornea is avascular and immunologically privileged, making corneal transplantation the standard eye-donation graft with a very low rejection rate.' }
  ]);
  CVS.after('E-C5', [
    { id: 'E22', src: 'AC70', core: true, q: 'A 50-year-old woman takes a drug causing overstimulation of the parasympathetic nervous system. What effect will this have on her eyeballs?', o: ['Pupil dilation', 'Flattening of the lens', 'Contraction of the ciliary muscle', 'Constriction of corneal vessels', 'Enhancement of long-distance vision'], a: 2, ex: 'Parasympathetic (CN III) stimulation contracts sphincter pupillae (miosis) and contracts the ciliary muscle, slackening the zonules so the lens thickens for near vision (accommodation). The cornea is avascular.' },
    { id: 'E23', src: 'AC70', q: 'Which structure produces aqueous humor?', o: ['Ciliary epithelium', 'Corneal epithelium', 'Canal of Schlemm', 'Conjunctiva', 'Ora serrata'], a: 0, ex: 'The non-pigmented ciliary epithelium covering the ciliary processes secretes aqueous humor into the posterior chamber; it later drains via the trabecular meshwork and canal of Schlemm.' },
    { id: 'E24', src: 'AC72 · AC78', q: 'Which structure is located at the iridocorneal angle (corneoscleral junction)?', o: ['Ora serrata', 'Trabecular meshwork', 'Zonular fibers', 'Lamina cribrosa', 'Fovea centralis'], a: 1, ex: 'The trabecular meshwork sits in the iridocorneal angle at the corneoscleral junction (limbus), filtering aqueous humor into the canal of Schlemm.' },
    { id: 'E25', src: 'AC71 · AC72', q: 'Which structure is innervated by postganglionic fibers from the superior cervical sympathetic ganglion?', o: ['Ciliary muscle', 'Dilator pupillae muscle', 'Sphincter pupillae muscle', 'Stapedius muscle', 'Tensor tympani muscle'], a: 1, ex: 'Postganglionic sympathetic fibers from the superior cervical ganglion supply dilator pupillae (mydriasis) and superior tarsal muscle. Ciliary and sphincter pupillae are parasympathetic (CN III).' }
  ]);
  CVS.after('E-C6', [
    { id: 'E28', src: 'AC71 · AC73 · AC76 · AC79', core: true, q: 'When an examiner touches the cornea with a wisp of cotton, the normal response is a blink. Which nerves are involved in this reflex?', o: ['Frontal and facial nerves', 'Lacrimal and optic nerves', 'Nasociliary and facial nerves', 'Optic and ophthalmic nerves', 'Nasociliary and frontal nerves'], a: 2, ex: 'Corneal reflex arc: afferent = nasociliary nerve (via long ciliary nerves, V1); efferent = facial nerve (CN VII) to orbicularis oculi (closing both eyes).' }
  ]);
  CVS.after('H-C1', [
    { id: 'H1', src: 'AC72 · AC78 · AC79', core: true, q: 'Which part of the external ear (pinna) contains no cartilage and is most suitable for ear piercing?', o: ['Lobule', 'Helix', 'Antihelix', 'Concha', 'Tragus'], a: 0, ex: 'The pinna is supported by elastic cartilage throughout the helix, antihelix, concha and tragus, except the lobule (earlobe), which consists only of fibrous and adipose tissue.' }
  ]);
  CVS.after('H-C2', [
    { id: 'H6', src: 'AC73', q: 'Which structure forms the lateral wall of the middle ear?', o: ['Opening to mastoid antrum', 'Tympanic membrane', 'Facial nerve', 'Oval window', 'Opening of auditory tube'], a: 1, ex: 'The lateral (membranous) wall of the tympanic cavity is formed mainly by the tympanic membrane. Aditus and facial canal are posterior, oval window is medial, auditory tube is anterior.' },
    { id: 'H7', src: 'AC72', q: 'Which structure is NOT part of the posterior wall of the middle ear?', o: ['Facial canal', 'Aditus to mastoid antrum', 'Entrance for chorda tympani nerve', 'Prominence of lateral semicircular canal', 'Pyramidal eminence for stapedius muscle'], a: 3, ex: 'The prominence of the lateral semicircular canal bulges on the medial (labyrinthine) wall just above the facial canal. The aditus, pyramidal eminence, descending facial canal and chorda tympani opening belong to the posterior wall.', flag: 'AC70 Q7 asked the same stem with “canal for tensor tympani muscle” (anterior wall) as the exception.' },
    { id: 'H8', src: 'AC78', q: 'Which structure is NOT located on the medial wall of the middle ear?', o: ['Round window', 'Oval window', 'Promontory with tympanic plexus', 'Prominence of facial canal', 'Opening to auditory tube'], a: 4, ex: 'The medial (labyrinthine) wall displays the promontory (tympanic plexus), oval window, round window and prominence of the facial canal. The opening to the auditory tube is on the anterior wall.' },
    { id: 'H9', src: 'AC74 · AC76 · AC77', q: 'What is the location of the mastoid air cells relative to the tympanic cavity?', o: ['Posterior', 'Inferior', 'Lateral', 'Medial', 'Superior'], a: 0, ex: 'The mastoid antrum and mastoid air cells lie directly behind the tympanic cavity, communicating with it through the aditus on the posterior (mastoid) wall.' },
    { id: 'H10', src: 'AC77', q: 'Which structure enters the tympanic cavity through the posterior wall and exits through the anterior wall?', o: ['Chorda tympani nerve', 'Facial nerve', 'Stapes', 'Incus', 'Malleus'], a: 0, ex: 'The chorda tympani branches off CN VII in the posterior wall, crosses the medial surface of the tympanic membrane (between malleus and incus), and exits anteriorly via the petrotympanic fissure.' }
  ]);
  CVS.after('H-C3', [
    { id: 'H14', src: 'AC71 · AC75', core: true, q: 'Which cranial nerve supplies the tensor tympani muscle?', o: ['Facial nerve', 'Vagus nerve', 'Ophthalmic nerve', 'Mandibular nerve', 'Glossopharyngeal nerve'], a: 3, ex: 'Tensor tympani is a 1st-arch muscle (attaching to the malleus) supplied by the mandibular nerve (CN V3). Stapedius is a 2nd-arch muscle supplied by the facial nerve (CN VII).' }
  ]);
  CVS.after('H-C4', [
    { id: 'H18', src: 'AC74 · AC76', core: true, q: 'Where is the vestibular receptor for head rotation (angular acceleration) located?', o: ['Utricle', 'Saccule', 'Cochlear duct', 'Endolymphatic sac', 'Ampulla of semicircular duct'], a: 4, ex: 'Head rotation is detected by the crista ampullaris inside the ampulla of each semicircular duct. The maculae of the utricle and saccule detect linear acceleration and head tilt (gravity).' },
    { id: 'H19', src: 'AC73', q: 'Which structure directly contacts the stereocilia of hair cells in the macula?', o: ['Tectorial membrane', 'Tympanic membrane', 'Vestibular membrane', 'Otolithic membrane', 'Basilar membrane'], a: 3, ex: 'Macular hair cells (utricle and saccule) project into the gelatinous otolithic membrane weighted with otoconia. Crista hair cells contact the cupula; organ of Corti hair cells contact the tectorial membrane.' },
    { id: 'H20', src: 'AC68', q: 'Which part of the membranous labyrinth does NOT contain vestibular or auditory receptors?', o: ['Cochlear duct', 'Endolymphatic sac', 'Utricle', 'Saccule', 'Semicircular duct'], a: 1, ex: 'The endolymphatic duct and sac absorb endolymph and contain no sensory receptors. Cochlear duct holds the organ of Corti; utricle and saccule hold maculae; semicircular ducts hold cristae.' },
    { id: 'H21', src: 'AC79', q: 'Which cranial nerve carries signals from the vestibular receptors?', o: ['CN V', 'CN VI', 'CN VII', 'CN VIII', 'CN IX'], a: 3, ex: 'Vestibular hair cells synapse with bipolar neurons of the vestibular ganglion whose axons form the vestibular division of CN VIII (vestibulocochlear nerve).' }
  ]);
  CVS.after('H-C5', [
    { id: 'H24', src: 'AC74 · AC78', core: true, q: 'Which structure directly contacts the stereocilia of hair cells in the organ of Corti?', o: ['Tectorial membrane', 'Tympanic membrane', 'Vestibular membrane', 'Otolithic membrane', 'Basilar membrane'], a: 0, ex: 'Sound vibrates the basilar membrane, shearing the stereocilia of cochlear hair cells against the overlying gelatinous tectorial membrane.' },
    { id: 'H25', src: 'AC78', core: true, q: 'Which structure contains the auditory receptors for high-frequency sound waves?', o: ['Basal part of cochlea', 'Helicotrema', 'Middle part of cochlea', 'Round window', 'Oval window'], a: 0, ex: 'At the base of the cochlea the basilar membrane is narrow and stiff, resonating with high-frequency sounds; toward the apex (helicotrema) it is wide and flexible for low frequencies.' },
    { id: 'H26', src: 'AC79', q: 'Where are the auditory receptors located?', o: ['Scala vestibuli', 'Scala tympani', 'Semicircular duct', 'Cochlear duct', 'Stria vascularis'], a: 3, ex: 'The organ of Corti sits on the basilar membrane inside the cochlear duct (scala media), bathed in endolymph secreted by the stria vascularis.' },
    { id: 'H27', src: 'AC68', q: 'Vibration of which structure is NOT related to hearing?', o: ['Basilar membrane', 'Vestibular membrane', 'Otolithic membrane', 'Tectorial membrane', 'Membrane of round window'], a: 2, ex: 'The otolithic membrane belongs to the vestibular maculae (utricle and saccule). Basilar, vestibular, tectorial and round-window membranes are all part of cochlear sound mechanics.' }
  ]);
  CVS.after('H-C6', [
    { id: 'H28', src: 'AC68 · AC70', core: true, q: 'Infection in the middle ear can directly spread to all of the following structures EXCEPT:', o: ['Meninges', 'Parotid gland', 'Mastoid air cells', 'Sigmoid sinus', 'Labyrinth (internal ear)'], a: 1, ex: 'Middle ear infection can spread upward through tegmen tympani to the meninges, backward via the aditus to mastoid air cells and the sigmoid sinus, and medially to the labyrinth—not directly to the parotid gland.' },
    { id: 'H29', src: 'AC79', core: true, q: 'Otitis media can spread to cause mastoiditis through which opening?', o: ['Oval window', 'Round window', 'Opening of Eustachian tube', 'Opening for tensor tympani', 'Aditus'], a: 4, ex: 'The aditus to the mastoid antrum on the posterior wall of the epitympanic recess connects the middle ear directly to the mastoid air cells.' },
    { id: 'H30', src: 'AC73 · AC74', core: true, q: 'Which structure is primarily damaged in noise-induced hearing loss?', o: ['Tympanic membrane', 'Malleus', 'Stapes', 'Vestibular membrane', 'Hair cells'], a: 4, ex: 'Loud noise causes sensorineural hearing loss by mechanically and metabolically damaging the cochlear hair cells (especially outer hair cells at the 3–4 kHz region), which cannot regenerate.' },
    { id: 'H31', src: 'AC71', q: 'Which nerve can be damaged as a complication of middle ear infection?', o: ['Facial nerve', 'Auriculotemporal nerve', 'Mandibular nerve', 'Glossopharyngeal nerve', 'Vagus nerve'], a: 0, ex: 'The facial nerve runs in the thin-walled facial canal along the medial and posterior walls of the tympanic cavity, placing it directly at risk in chronic otitis media.' }
  ]);
  CVS.after('X-C1', [
    { id: 'X1', src: 'AC71 · AC72', core: true, q: 'Which of the following structures is NOT an autonomic ganglion?', o: ['Sphenopalatine ganglion', 'Trigeminal ganglion', 'Ciliary ganglion', 'Otic ganglion', 'Submandibular ganglion'], a: 1, ex: 'The four cranial parasympathetic ganglia are ciliary (III), pterygopalatine/sphenopalatine (VII), submandibular (VII) and otic (IX). The trigeminal ganglion is a somatic sensory ganglion (like a DRG).' },
    { id: 'X2', src: 'AC68 · AC77', core: true, q: 'Which of the following structures conveys parasympathetic preganglionic fibers?', o: ['Greater petrosal nerve', 'Deep petrosal nerve', 'External carotid plexus', 'Internal carotid plexus', 'Cavernous plexus'], a: 0, ex: 'The greater petrosal nerve carries CN VII preganglionic parasympathetic fibers to the pterygopalatine ganglion. The deep petrosal nerve and the carotid/cavernous plexuses all carry postganglionic sympathetic fibers.', flag: 'AC77 also included Lesser petrosal nerve as option E, so both Greater and Lesser petrosal nerves were keyed in AC77; AC68’s unambiguous five options are shown.' }
  ]);
  CVS.after('X-C2', [
    { id: 'X4', src: 'AC70', core: true, q: 'Which muscle will be paralyzed if there is a lesion of the cervical sympathetic trunk?', o: ['Superior rectus muscle', 'Superior oblique muscle', 'Inferior oblique muscle', 'Superior tarsal muscle', 'Ciliary muscle'], a: 3, ex: 'Sympathetic fibers from the superior cervical ganglion supply the smooth superior tarsal (Müller) muscle; its paralysis causes the mild ptosis of Horner syndrome. The rectus/oblique muscles are somatic (III/IV) and ciliary is parasympathetic (III).' },
    { id: 'X5', src: 'AC79', q: 'What is an effect of sympathetic stimulation on the face and eye?', o: ['Increased watery saliva', 'Lens accommodation', 'Miosis', 'Increased lacrimal secretion', 'Increased sweat secretion'], a: 4, ex: 'Postganglionic sympathetic fibers along the external carotid plexus stimulate facial sweat glands (sudomotor). Watery saliva, lens accommodation, miosis and lacrimation are all parasympathetic effects.' }
  ]);
  CVS.after('X-C3', [
    { id: 'X6', src: 'AC76', core: true, q: 'A 75-year-old man presents with drooping of the right eyelid and diplopia. Physical examination shows the right eye pointing downwards and outwards. Which nerve is most likely affected?', o: ['Optic nerve', 'Trochlear nerve', 'Abducens nerve', 'Facial nerve', 'Oculomotor nerve'], a: 4, ex: 'CN III palsy weakens levator palpebrae (ptosis) and SR/IR/MR/IO, leaving lateral rectus (VI) and superior oblique (IV) unopposed so the eye turns “down and out” (often with a dilated pupil from lost parasympathetic tone).' }
  ]);
  CVS.after('X-C4', [
    { id: 'X10', src: 'AC79', core: true, q: 'Which nerve conveys parasympathetic fibers to the pterygopalatine ganglion?', o: ['Lesser petrosal nerve', 'Greater petrosal nerve', 'Deep petrosal nerve', 'Auriculotemporal nerve', 'Chorda tympani nerve'], a: 1, ex: 'Superior salivatory nucleus → CN VII → greater petrosal nerve → nerve of the pterygoid canal → pterygopalatine ganglion → lacrimal, nasal and palatal glands.' },
    { id: 'X11', src: 'AC70 · AC74', q: 'A patient presents with dryness of the nose, eyes, and palate. Which ganglion is most likely abnormal?', o: ['Otic ganglion', 'Inferior cervical ganglion', 'Submandibular ganglion', 'Sphenopalatine ganglion', 'Superior cervical ganglion'], a: 3, ex: 'The sphenopalatine (pterygopalatine) ganglion supplies secretomotor parasympathetic fibers to the lacrimal gland, nasal mucosa and palatal glands.', flag: 'AC70 asked “จมูกแห้ง น้ำตาแห้ง”; AC74 recalled “dryness of nose, face and palate” (“face” was likely a recall slip for eyes/tears).' }
  ]);
  CVS.after('X-C5', [
    { id: 'X14', src: 'AC79', core: true, q: 'Which of the following is NOT a result of facial nerve paralysis?', o: ['Hyperacusis', 'Reduced lacrimal secretion', 'Reduced parotid duct secretion', 'Loss of taste on the anterior two-thirds of the tongue', 'Hemifacial paralysis'], a: 2, ex: 'Parotid secretion is controlled by CN IX via the lesser petrosal nerve and otic ganglion, not CN VII. Facial nerve lesions proximal to the geniculate ganglion cause hemifacial paralysis, hyperacusis (stapedius), dry eye (greater petrosal) and anterior 2/3 taste loss (chorda tympani).' }
  ]);
  CVS.after('X-C6', [
    { id: 'X17', src: 'AC70 · AC71 · AC77', core: true, q: 'Which nerve conveys parasympathetic preganglionic fibers to the otic ganglion to supply the parotid gland?', o: ['Lingual nerve', 'Deep petrosal nerve', 'Lesser petrosal nerve', 'Chorda tympani nerve', 'Greater petrosal nerve'], a: 2, ex: 'CN IX → tympanic nerve → tympanic plexus → lesser petrosal nerve (preganglionic, through foramen ovale) → otic ganglion → auriculotemporal nerve (postganglionic) → parotid gland.', flag: 'AC71 yellow key mistakenly highlighted auriculotemporal nerve (which carries postganglionic fibers); AC70 and AC77 correctly key lesser petrosal nerve.' },
    { id: 'X18', src: 'AC73 · AC76', q: 'Which nerve conveys postganglionic parasympathetic fibers from the otic ganglion to supply the parotid gland?', o: ['Chorda tympani nerve', 'Auriculotemporal nerve', 'Greater petrosal nerve', 'Lesser petrosal nerve'], a: 1, ex: 'Chorda tympani, greater petrosal and lesser petrosal all carry preganglionic parasympathetic fibers. After synapsing in the otic ganglion, postganglionic fibers ride the auriculotemporal nerve (V3) to the parotid gland.', flag: 'Only four options were recalled in AC73 and AC76.' }
  ]);
  CVS.after('Y-C2', [
    { id: 'Y3', src: 'AC79', q: 'A patient has a paracentral lumbar disc herniation with an intact knee jerk, absent ankle reflex, numbness of the lateral side of the foot, and gluteus maximus/hamstring weakness. Which intervertebral disc level is injured?', o: ['L1–L2', 'L2–L3', 'L3–L4', 'L4–L5', 'L5–S1'], a: 4, ex: 'Absent ankle reflex, lateral foot numbness and gluteus maximus weakness localize to the S1 nerve root. A paracentral disc hits the traversing (lower) root, so S1 compression comes from the L5–S1 disc.', flag: 'The recall also wrote “dorsiflexion lost” (which is an L5 sign) alongside the S1 exam clues (absent ankle reflex, lateral foot numbness); the official key is L5–S1.' }
  ]);
  CVS.after('Y-C4', [
    { id: 'Y4', src: 'AC74 · AC76', core: true, q: 'Injury to the superior cervical sympathetic trunk will NOT cause which of the following?', o: ['Ptosis', 'Miosis', 'Exophthalmos', 'Anhidrosis', 'Vasodilation of facial vessels'], a: 2, ex: 'Sympathetic loss produces Horner syndrome: ptosis, miosis, anhidrosis, apparent enophthalmos (NOT exophthalmos) and facial vasodilation/flushing from lost vasoconstrictor tone.' }
  ]);
  CVS.after('Y-C5', [
    { id: 'Y5', src: 'AC68', core: true, q: 'A tumor compresses the superior cervical sympathetic trunk. Which of the following findings will NOT be detected on examination?', o: ['Miosis', 'Facial anhidrosis', 'Enophthalmos', 'Ptosis', 'Loss of direct light reflex'], a: 4, ex: 'The pupillary light reflex uses CN II (afferent) and parasympathetic CN III (efferent to sphincter pupillae). Because Horner syndrome only interrupts the sympathetic dilator pathway, the direct and consensual light reflexes remain intact.' },
    { id: 'Y6', src: 'AC76', core: true, q: 'When light is shone into the right eye and constriction of the right pupil is observed, what is the efferent nerve of this reflex?', o: ['Right optic nerve', 'Right oculomotor nerve', 'Left optic nerve', 'Left oculomotor nerve'], a: 1, ex: 'Direct light reflex of the right eye: afferent = right optic nerve (CN II) → midbrain pretectal &amp; Edinger–Westphal nuclei → efferent = right oculomotor nerve (CN III) → ciliary ganglion → sphincter pupillae.' }
  ]);
})();
